def pair_sum(nums, target):
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[l] + nums[r]
        if s == target:
            return [l, r]
        if s < target:
            l += 1
        else:
            r -= 1
    return []

class Solution {
    public int[] pairSum(int[] nums, int target) {
        int l = 0, r = nums.length - 1;
        while (l < r) {
            int s = nums[l] + nums[r];
            if (s == target) return new int[]{l, r};
            if (s < target) l++;
            else r--;
        }
        return new int[0];
    }
}

def is_clean_palindrome(s):
    l, r = 0, len(s) - 1
    while l < r:
        if not s[l].isalnum():
            l += 1
        elif not s[r].isalnum():
            r -= 1
        elif s[l].lower() != s[r].lower():
            return False
        else:
            l, r = l + 1, r - 1
    return True

class Solution {
    public boolean isCleanPalindrome(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (!Character.isLetterOrDigit(s.charAt(l))) l++;
            else if (!Character.isLetterOrDigit(s.charAt(r))) r--;
            else if (Character.toLowerCase(s.charAt(l)) != Character.toLowerCase(s.charAt(r))) return false;
            else { l++; r--; }
        }
        return true;
    }
}

def reverse_chars(chars):
    l, r = 0, len(chars) - 1
    while l < r:
        chars[l], chars[r] = chars[r], chars[l]
        l, r = l + 1, r - 1

class Solution {
    public void reverseChars(char[] chars) {
        int l = 0, r = chars.length - 1;
        while (l < r) {
            char t = chars[l]; chars[l] = chars[r]; chars[r] = t;
            l++; r--;
        }
    }
}

def move_zeros(nums):
    w = 0
    for r in range(len(nums)):
        if nums[r] != 0:
            nums[w], nums[r] = nums[r], nums[w]
            w += 1

class Solution {
    public void moveZeros(int[] nums) {
        int w = 0;
        for (int r = 0; r < nums.length; r++) {
            if (nums[r] != 0) {
                int t = nums[w]; nums[w] = nums[r]; nums[r] = t;
                w++;
            }
        }
    }
}

def remove_repeats(nums):
    w = 1
    for r in range(1, len(nums)):
        if nums[r] != nums[w - 1]:
            nums[w] = nums[r]
            w += 1
    return w

class Solution {
    public int removeRepeats(int[] nums) {
        int w = 1;
        for (int r = 1; r < nums.length; r++) {
            if (nums[r] != nums[w - 1]) {
                nums[w] = nums[r];
                w++;
            }
        }
        return w;
    }
}

def keep_two(nums):
    w = 0
    for x in nums:
        if w < 2 or x != nums[w - 2]:
            nums[w] = x
            w += 1
    return w

class Solution {
    public int keepTwo(int[] nums) {
        int w = 0;
        for (int x : nums) {
            if (w < 2 || x != nums[w - 2]) {
                nums[w] = x;
                w++;
            }
        }
        return w;
    }
}

def merge_into(a, m, b, n):
    i, j, k = m - 1, n - 1, m + n - 1
    while j >= 0:
        if i >= 0 and a[i] > b[j]:
            a[k] = a[i]
            i -= 1
        else:
            a[k] = b[j]
            j -= 1
        k -= 1

class Solution {
    public void mergeInto(int[] a, int m, int[] b, int n) {
        int i = m - 1, j = n - 1, k = m + n - 1;
        while (j >= 0) {
            if (i >= 0 && a[i] > b[j]) a[k--] = a[i--];
            else a[k--] = b[j--];
        }
    }
}

def sorted_squares(nums):
    res = [0] * len(nums)
    l, r = 0, len(nums) - 1
    for k in range(len(nums) - 1, -1, -1):
        if abs(nums[l]) > abs(nums[r]):
            res[k] = nums[l] * nums[l]
            l += 1
        else:
            res[k] = nums[r] * nums[r]
            r -= 1
    return res

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length, l = 0, r = n - 1;
        int[] res = new int[n];
        for (int k = n - 1; k >= 0; k--) {
            if (Math.abs(nums[l]) > Math.abs(nums[r])) { res[k] = nums[l] * nums[l]; l++; }
            else { res[k] = nums[r] * nums[r]; r--; }
        }
        return res;
    }
}

def max_water(heights):
    l, r, best = 0, len(heights) - 1, 0
    while l < r:
        area = min(heights[l], heights[r]) * (r - l)
        best = max(best, area)
        if heights[l] < heights[r]:
            l += 1
        else:
            r -= 1
    return best

class Solution {
    public int maxWater(int[] heights) {
        int l = 0, r = heights.length - 1, best = 0;
        while (l < r) {
            int area = Math.min(heights[l], heights[r]) * (r - l);
            best = Math.max(best, area);
            if (heights[l] < heights[r]) l++;
            else r--;
        }
        return best;
    }
}

def three_sum(nums):
    nums.sort()
    res = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, len(nums) - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append([nums[i], nums[l], nums[r]])
                l += 1
                while l < r and nums[l] == nums[l - 1]:
                    l += 1
    return res

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < nums.length - 2; i++) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int s = nums[i] + nums[l] + nums[r];
                if (s < 0) l++;
                else if (s > 0) r--;
                else {
                    res.add(List.of(nums[i], nums[l], nums[r]));
                    l++;
                    while (l < r && nums[l] == nums[l - 1]) l++;
                }
            }
        }
        return res;
    }
}

def three_sum_closest(nums, target):
    nums.sort()
    best = nums[0] + nums[1] + nums[2]
    for i in range(len(nums) - 2):
        l, r = i + 1, len(nums) - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if abs(s - target) < abs(best - target):
                best = s
            if s < target:
                l += 1
            elif s > target:
                r -= 1
            else:
                return s
    return best

class Solution {
    public int threeSumClosest(int[] nums, int target) {
        Arrays.sort(nums);
        int best = nums[0] + nums[1] + nums[2];
        for (int i = 0; i < nums.length - 2; i++) {
            int l = i + 1, r = nums.length - 1;
            while (l < r) {
                int s = nums[i] + nums[l] + nums[r];
                if (Math.abs(s - target) < Math.abs(best - target)) best = s;
                if (s < target) l++;
                else if (s > target) r--;
                else return s;
            }
        }
        return best;
    }
}

def sort_colors(nums):
    lo, mid, hi = 0, 0, len(nums) - 1
    while mid <= hi:
        if nums[mid] == 0:
            nums[lo], nums[mid] = nums[mid], nums[lo]
            lo, mid = lo + 1, mid + 1
        elif nums[mid] == 1:
            mid += 1
        else:
            nums[mid], nums[hi] = nums[hi], nums[mid]
            hi -= 1

class Solution {
    public void sortColors(int[] nums) {
        int lo = 0, mid = 0, hi = nums.length - 1;
        while (mid <= hi) {
            if (nums[mid] == 0) { int t = nums[lo]; nums[lo++] = nums[mid]; nums[mid++] = t; }
            else if (nums[mid] == 1) mid++;
            else { int t = nums[hi]; nums[hi--] = nums[mid]; nums[mid] = t; }
        }
    }
}

def trap(height):
    l, r = 0, len(height) - 1
    left_max = right_max = water = 0
    while l < r:
        if height[l] < height[r]:
            left_max = max(left_max, height[l])
            water += left_max - height[l]
            l += 1
        else:
            right_max = max(right_max, height[r])
            water += right_max - height[r]
            r -= 1
    return water

class Solution {
    public int trap(int[] height) {
        int l = 0, r = height.length - 1, leftMax = 0, rightMax = 0, water = 0;
        while (l < r) {
            if (height[l] < height[r]) {
                leftMax = Math.max(leftMax, height[l]);
                water += leftMax - height[l++];
            } else {
                rightMax = Math.max(rightMax, height[r]);
                water += rightMax - height[r--];
            }
        }
        return water;
    }
}

def is_subsequence(s, t):
    i = 0
    for j in range(len(t)):
        if i < len(s) and s[i] == t[j]:
            i += 1
    return i == len(s)

class Solution {
    public boolean isSubsequence(String s, String t) {
        int i = 0;
        for (int j = 0; j < t.length(); j++) {
            if (i < s.length() && s.charAt(i) == t.charAt(j)) i++;
        }
        return i == s.length();
    }
}

def rotate(nums, k):
    k %= len(nums)

    def reverse(l, r):
        while l < r:
            nums[l], nums[r] = nums[r], nums[l]
            l, r = l + 1, r - 1

    reverse(0, len(nums) - 1)
    reverse(0, k - 1)
    reverse(k, len(nums) - 1)

class Solution {
    public void rotate(int[] nums, int k) {
        k %= nums.length;
        reverse(nums, 0, nums.length - 1);
        reverse(nums, 0, k - 1);
        reverse(nums, k, nums.length - 1);
    }

    private void reverse(int[] a, int l, int r) {
        while (l < r) { int t = a[l]; a[l++] = a[r]; a[r--] = t; }
    }
}

def min_boats(people, limit):
    people.sort()
    l, r, boats = 0, len(people) - 1, 0
    while l <= r:
        if people[l] + people[r] <= limit:
            l += 1
        boats += 1
        r -= 1
    return boats

class Solution {
    public int minBoats(int[] people, int limit) {
        Arrays.sort(people);
        int l = 0, r = people.length - 1, boats = 0;
        while (l <= r) {
            if (people[l] + people[r] <= limit) l++;
            boats++;
            r--;
        }
        return boats;
    }
}

def almost_palindrome(s):
    def is_pal(l, r):
        while l < r:
            if s[l] != s[r]:
                return False
            l, r = l + 1, r - 1
        return True

    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            return is_pal(l + 1, r) or is_pal(l, r - 1)
        l, r = l + 1, r - 1
    return True

class Solution {
    public boolean almostPalindrome(String s) {
        int l = 0, r = s.length() - 1;
        while (l < r) {
            if (s.charAt(l) != s.charAt(r)) return isPal(s, l + 1, r) || isPal(s, l, r - 1);
            l++; r--;
        }
        return true;
    }

    private boolean isPal(String s, int l, int r) {
        while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;
        return true;
    }
}

def reverse_vowels(s):
    chars, vowels = list(s), set("aeiouAEIOU")
    l, r = 0, len(chars) - 1
    while l < r:
        if chars[l] not in vowels:
            l += 1
        elif chars[r] not in vowels:
            r -= 1
        else:
            chars[l], chars[r] = chars[r], chars[l]
            l, r = l + 1, r - 1
    return "".join(chars)

class Solution {
    public String reverseVowels(String s) {
        char[] c = s.toCharArray();
        String vowels = "aeiouAEIOU";
        int l = 0, r = c.length - 1;
        while (l < r) {
            if (vowels.indexOf(c[l]) < 0) l++;
            else if (vowels.indexOf(c[r]) < 0) r--;
            else { char t = c[l]; c[l++] = c[r]; c[r--] = t; }
        }
        return new String(c);
    }
}

def backspace_equal(s, t):
    def survivor(x, i):
        skip = 0
        while i >= 0:
            if x[i] == "#":
                skip += 1
            elif skip:
                skip -= 1
            else:
                break
            i -= 1
        return i

    i, j = len(s) - 1, len(t) - 1
    while True:
        i, j = survivor(s, i), survivor(t, j)
        if i < 0 or j < 0:
            return i < 0 and j < 0
        if s[i] != t[j]:
            return False
        i, j = i - 1, j - 1

class Solution {
    public boolean backspaceEqual(String s, String t) {
        int i = s.length() - 1, j = t.length() - 1;
        while (true) {
            i = survivor(s, i); j = survivor(t, j);
            if (i < 0 || j < 0) return i < 0 && j < 0;
            if (s.charAt(i) != t.charAt(j)) return false;
            i--; j--;
        }
    }

    private int survivor(String x, int i) {
        int skip = 0;
        for (; i >= 0; i--) {
            if (x.charAt(i) == '#') skip++;
            else if (skip > 0) skip--;
            else break;
        }
        return i;
    }
}

def next_arrangement(nums):
    i = len(nums) - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i >= 0:
        j = len(nums) - 1
        while nums[j] <= nums[i]:
            j -= 1
        nums[i], nums[j] = nums[j], nums[i]
    l, r = i + 1, len(nums) - 1
    while l < r:
        nums[l], nums[r] = nums[r], nums[l]
        l, r = l + 1, r - 1

class Solution {
    public void nextArrangement(int[] nums) {
        int i = nums.length - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = nums.length - 1;
            while (nums[j] <= nums[i]) j--;
            int t = nums[i]; nums[i] = nums[j]; nums[j] = t;
        }
        for (int l = i + 1, r = nums.length - 1; l < r; l++, r--) {
            int t = nums[l]; nums[l] = nums[r]; nums[r] = t;
        }
    }
}

def find_duplicate(nums):
    slow = fast = nums[0]
    while True:
        slow, fast = nums[slow], nums[nums[fast]]
        if slow == fast:
            break
    slow = nums[0]
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

class Solution {
    public int findDuplicate(int[] nums) {
        int slow = nums[0], fast = nums[0];
        do { slow = nums[slow]; fast = nums[nums[fast]]; } while (slow != fast);
        slow = nums[0];
        while (slow != fast) { slow = nums[slow]; fast = nums[fast]; }
        return slow;
    }
}

def common_values(a, b):
    i = j = 0
    res = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            res.append(a[i])
            i, j = i + 1, j + 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return res

class Solution {
    public List<Integer> commonValues(int[] a, int[] b) {
        List<Integer> res = new ArrayList<>();
        int i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] == b[j]) { res.add(a[i]); i++; j++; }
            else if (a[i] < b[j]) i++;
            else j++;
        }
        return res;
    }
}

def min_sub_array_len(s, nums):
    total, min_len, left = 0, len(nums) + 1, 0
    for right in range(len(nums)):
        total += nums[right]
        while total >= s:
            min_len = min(min_len, right - left + 1)
            total -= nums[left]
            left += 1
    return min_len if min_len <= len(nums) else 0

class Solution {
    public int minSubArrayLen(int s, int[] nums) {
        int sum = 0, minLen = nums.length + 1, left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            for (; sum >= s; sum -= nums[left], left++) {
                minLen = Math.min(minLen, right - left + 1);
            }
        }
        return minLen <= nums.length ? minLen : 0;
    }
}

def longest_unique(s):
    count, best, left = {}, 0, 0
    for right in range(len(s)):
        c = s[right]
        count[c] = count.get(c, 0) + 1
        while count[c] > 1:
            count[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int longestUnique(String s) {
        int[] count = new int[128];
        int best = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            count[c]++;
            for (; count[c] > 1; left++) count[s.charAt(left)]--;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def longest_unique(s):
    last, best, left = {}, 0, 0
    for right in range(len(s)):
        if last.get(s[right], -1) >= left:
            left = last[s[right]] + 1
        last[s[right]] = right
        best = max(best, right - left + 1)
    return best

class Solution {
    public int longestUnique(String s) {
        Map<Character, Integer> last = new HashMap<>();
        int best = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            char c = s.charAt(right);
            if (last.getOrDefault(c, -1) >= left) left = last.get(c) + 1;
            last.put(c, right);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def best_window_sum(nums, k):
    total, best, left = 0, float("-inf"), 0
    for right in range(len(nums)):
        total += nums[right]
        if right - left + 1 > k:
            total -= nums[left]
            left += 1
        if right - left + 1 == k:
            best = max(best, total)
    return best

class Solution {
    public int bestWindowSum(int[] nums, int k) {
        int sum = 0, best = Integer.MIN_VALUE, left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            for (; right - left + 1 > k; left++) sum -= nums[left];
            if (right - left + 1 == k) best = Math.max(best, sum);
        }
        return best;
    }
}

def longest_after_changes(s, k):
    count, top, best, left = {}, 0, 0, 0
    for right in range(len(s)):
        count[s[right]] = count.get(s[right], 0) + 1
        top = max(top, count[s[right]])
        while right - left + 1 - top > k:
            count[s[left]] -= 1
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int longestAfterChanges(String s, int k) {
        int[] count = new int[26];
        int top = 0, best = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            top = Math.max(top, ++count[s.charAt(right) - 'A']);
            for (; right - left + 1 - top > k; left++) count[s.charAt(left) - 'A']--;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def contains_permutation(p, s):
    need, have, left = [0] * 26, [0] * 26, 0
    for c in p:
        need[ord(c) - 97] += 1
    for right in range(len(s)):
        have[ord(s[right]) - 97] += 1
        if right - left + 1 > len(p):
            have[ord(s[left]) - 97] -= 1
            left += 1
        if have == need:
            return True
    return False

class Solution {
    public boolean containsPermutation(String p, String s) {
        int[] need = new int[26], have = new int[26];
        for (char c : p.toCharArray()) need[c - 'a']++;
        for (int right = 0, left = 0; right < s.length(); right++) {
            have[s.charAt(right) - 'a']++;
            for (; right - left + 1 > p.length(); left++) have[s.charAt(left) - 'a']--;
            if (Arrays.equals(have, need)) return true;
        }
        return false;
    }
}

def anagram_starts(s, p):
    need, have, res, left = [0] * 26, [0] * 26, [], 0
    for c in p:
        need[ord(c) - 97] += 1
    for right in range(len(s)):
        have[ord(s[right]) - 97] += 1
        if right - left + 1 > len(p):
            have[ord(s[left]) - 97] -= 1
            left += 1
        if have == need:
            res.append(left)
    return res

class Solution {
    public List<Integer> anagramStarts(String s, String p) {
        int[] need = new int[26], have = new int[26];
        List<Integer> res = new ArrayList<>();
        for (char c : p.toCharArray()) need[c - 'a']++;
        for (int right = 0, left = 0; right < s.length(); right++) {
            have[s.charAt(right) - 'a']++;
            for (; right - left + 1 > p.length(); left++) have[s.charAt(left) - 'a']--;
            if (Arrays.equals(have, need)) res.add(left);
        }
        return res;
    }
}

def min_window(s, t):
    need = {}
    for c in t:
        need[c] = need.get(c, 0) + 1
    missing, min_len, start, left = len(t), len(s) + 1, 0, 0
    for right in range(len(s)):
        if need.get(s[right], 0) > 0:
            missing -= 1
        need[s[right]] = need.get(s[right], 0) - 1
        while missing == 0:
            if right - left + 1 < min_len:
                min_len, start = right - left + 1, left
            need[s[left]] += 1
            if need[s[left]] > 0:
                missing += 1
            left += 1
    return s[start:start + min_len] if min_len <= len(s) else ""

class Solution {
    public String minWindow(String s, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        int missing = t.length(), minLen = s.length() + 1, start = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            if (need[s.charAt(right)]-- > 0) missing--;
            for (; missing == 0; left++) {
                if (right - left + 1 < minLen) { minLen = right - left + 1; start = left; }
                if (++need[s.charAt(left)] > 0) missing++;
            }
        }
        return minLen <= s.length() ? s.substring(start, start + minLen) : "";
    }
}

def longest_ones(nums, k):
    zeros, best, left = 0, 0, 0
    for right in range(len(nums)):
        zeros += nums[right] == 0
        while zeros > k:
            zeros -= nums[left] == 0
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int longestOnes(int[] nums, int k) {
        int zeros = 0, best = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            if (nums[right] == 0) zeros++;
            for (; zeros > k; left++) if (nums[left] == 0) zeros--;
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def two_baskets(fruits):
    count, best, left = {}, 0, 0
    for right in range(len(fruits)):
        count[fruits[right]] = count.get(fruits[right], 0) + 1
        while len(count) > 2:
            count[fruits[left]] -= 1
            if count[fruits[left]] == 0:
                del count[fruits[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int twoBaskets(int[] fruits) {
        Map<Integer, Integer> count = new HashMap<>();
        int best = 0, left = 0;
        for (int right = 0; right < fruits.length; right++) {
            count.merge(fruits[right], 1, Integer::sum);
            for (; count.size() > 2; left++)
                if (count.merge(fruits[left], -1, Integer::sum) == 0) count.remove(fruits[left]);
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def longest_k_distinct(s, k):
    count, best, left = {}, 0, 0
    for right in range(len(s)):
        count[s[right]] = count.get(s[right], 0) + 1
        while len(count) > k:
            count[s[left]] -= 1
            if count[s[left]] == 0:
                del count[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int longestKDistinct(String s, int k) {
        Map<Character, Integer> count = new HashMap<>();
        int best = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            count.merge(s.charAt(right), 1, Integer::sum);
            for (; count.size() > k; left++)
                if (count.merge(s.charAt(left), -1, Integer::sum) == 0) count.remove(s.charAt(left));
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def count_small_products(nums, k):
    prod, count, left = 1, 0, 0
    for right in range(len(nums)):
        prod *= nums[right]
        while prod >= k and left <= right:
            prod //= nums[left]
            left += 1
        count += right - left + 1
    return count

class Solution {
    public int countSmallProducts(int[] nums, int k) {
        long prod = 1;
        int count = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            prod *= nums[right];
            for (; prod >= k && left <= right; left++) prod /= nums[left];
            count += right - left + 1;
        }
        return count;
    }
}

from collections import deque

def window_maxes(nums, k):
    dq, res = deque(), []
    for right in range(len(nums)):
        while dq and nums[dq[-1]] <= nums[right]:
            dq.pop()
        dq.append(right)
        if dq[0] <= right - k:
            dq.popleft()
        if right >= k - 1:
            res.append(nums[dq[0]])
    return res

class Solution {
    public int[] windowMaxes(int[] nums, int k) {
        Deque<Integer> dq = new ArrayDeque<>();
        int[] res = new int[nums.length - k + 1];
        for (int right = 0; right < nums.length; right++) {
            while (!dq.isEmpty() && nums[dq.peekLast()] <= nums[right]) dq.pollLast();
            dq.addLast(right);
            if (dq.peekFirst() <= right - k) dq.pollFirst();
            if (right >= k - 1) res[right - k + 1] = nums[dq.peekFirst()];
        }
        return res;
    }
}

def max_profit(prices):
    best, left = 0, 0
    for right in range(1, len(prices)):
        if prices[right] < prices[left]:
            left = right
        else:
            best = max(best, prices[right] - prices[left])
    return best

class Solution {
    public int maxProfit(int[] prices) {
        int best = 0, left = 0;
        for (int right = 1; right < prices.length; right++) {
            if (prices[right] < prices[left]) left = right;
            else best = Math.max(best, prices[right] - prices[left]);
        }
        return best;
    }
}

def nearby_duplicate(nums, k):
    window, left = set(), 0
    for right in range(len(nums)):
        if right - left > k:
            window.discard(nums[left])
            left += 1
        if nums[right] in window:
            return True
        window.add(nums[right])
    return False

class Solution {
    public boolean nearbyDuplicate(int[] nums, int k) {
        Set<Integer> window = new HashSet<>();
        for (int right = 0, left = 0; right < nums.length; right++) {
            for (; right - left > k; left++) window.remove(nums[left]);
            if (!window.add(nums[right])) return true;
        }
        return false;
    }
}

def most_vowels(s, k):
    count, best, left = 0, 0, 0
    for right in range(len(s)):
        count += s[right] in "aeiou"
        if right - left + 1 > k:
            count -= s[left] in "aeiou"
            left += 1
        best = max(best, count)
    return best

class Solution {
    public int mostVowels(String s, int k) {
        String v = "aeiou";
        int count = 0, best = 0, left = 0;
        for (int right = 0; right < s.length(); right++) {
            if (v.indexOf(s.charAt(right)) >= 0) count++;
            for (; right - left + 1 > k; left++) if (v.indexOf(s.charAt(left)) >= 0) count--;
            best = Math.max(best, count);
        }
        return best;
    }
}

def best_contiguous(nums):
    total, best, left = 0, nums[0], 0
    for right in range(len(nums)):
        if total < 0:
            total, left = 0, right
        total += nums[right]
        best = max(best, total)
    return best

class Solution {
    public int bestContiguous(int[] nums) {
        int sum = 0, best = nums[0];
        for (int right = 0; right < nums.length; right++) {
            if (sum < 0) sum = 0;
            sum += nums[right];
            best = Math.max(best, sum);
        }
        return best;
    }
}

def card_points(cards, k):
    size, total = len(cards) - k, sum(cards)
    window, smallest, left = 0, total, 0
    for right in range(len(cards)):
        window += cards[right]
        if right - left + 1 > size:
            window -= cards[left]
            left += 1
        if right - left + 1 == size:
            smallest = min(smallest, window)
    return total - (smallest if size else 0)

class Solution {
    public int cardPoints(int[] cards, int k) {
        int size = cards.length - k, total = 0, sum = 0, left = 0;
        for (int c : cards) total += c;
        int smallest = total;
        for (int right = 0; right < cards.length; right++) {
            sum += cards[right];
            for (; right - left + 1 > size; left++) sum -= cards[left];
            if (right - left + 1 == size) smallest = Math.min(smallest, sum);
        }
        return total - (size == 0 ? 0 : smallest);
    }
}

def max_frequency(nums, k):
    nums.sort()
    total, best, left = 0, 0, 0
    for right in range(len(nums)):
        total += nums[right]
        while nums[right] * (right - left + 1) - total > k:
            total -= nums[left]
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int maxFrequency(int[] nums, int k) {
        Arrays.sort(nums);
        long sum = 0;
        int best = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            sum += nums[right];
            for (; (long) nums[right] * (right - left + 1) - sum > k; left++) sum -= nums[left];
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

def exactly_k_odd(nums, k):
    def at_most(k):
        odd, count, left = 0, 0, 0
        for right in range(len(nums)):
            odd += nums[right] % 2
            while odd > k:
                odd -= nums[left] % 2
                left += 1
            count += right - left + 1
        return count

    return at_most(k) - at_most(k - 1)

class Solution {
    public int exactlyKOdd(int[] nums, int k) {
        return atMost(nums, k) - atMost(nums, k - 1);
    }

    private int atMost(int[] nums, int k) {
        int odd = 0, count = 0, left = 0;
        for (int right = 0; right < nums.length; right++) {
            odd += nums[right] % 2;
            for (; odd > k; left++) odd -= nums[left] % 2;
            count += right - left + 1;
        }
        return count;
    }
}

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i
    return []

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Map<Integer, Integer> seen = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            Integer j = seen.get(target - nums[i]);
            if (j != null) return new int[]{j, i};
            seen.put(nums[i], i);
        }
        return new int[0];
    }
}

def two_sum(nums, target):
    idx = sorted(range(len(nums)), key=lambda i: nums[i])
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[idx[l]] + nums[idx[r]]
        if s == target:
            return sorted([idx[l], idx[r]])
        if s < target:
            l += 1
        else:
            r -= 1
    return []

class Solution {
    public int[] twoSum(int[] nums, int target) {
        Integer[] idx = new Integer[nums.length];
        for (int i = 0; i < idx.length; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> Integer.compare(nums[a], nums[b]));
        int l = 0, r = nums.length - 1;
        while (l < r) {
            int s = nums[idx[l]] + nums[idx[r]];
            if (s == target) return new int[]{Math.min(idx[l], idx[r]), Math.max(idx[l], idx[r])};
            if (s < target) l++; else r--;
        }
        return new int[0];
    }
}

def has_repeat(nums):
    seen = set()
    for i, x in enumerate(nums):
        if x in seen:
            return True
        seen.add(x)
    return False

class Solution {
    public boolean hasRepeat(int[] nums) {
        Set<Integer> seen = new HashSet<>();
        for (int x : nums) {
            if (seen.contains(x)) return true;
            seen.add(x);
        }
        return false;
    }
}

def has_repeat(nums):
    nums.sort()
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            return True
    return False

class Solution {
    public boolean hasRepeat(int[] nums) {
        Arrays.sort(nums);
        for (int i = 1; i < nums.length; i++) if (nums[i] == nums[i - 1]) return true;
        return false;
    }
}

def same_letters(s, t):
    if len(s) != len(t):
        return False
    count = [0] * 26
    for a, b in zip(s, t):
        count[ord(a) - 97] += 1
        count[ord(b) - 97] -= 1
    return all(c == 0 for c in count)

class Solution {
    public boolean sameLetters(String s, String t) {
        if (s.length() != t.length()) return false;
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
            count[t.charAt(i) - 'a']--;
        }
        for (int c : count) if (c != 0) return false;
        return true;
    }
}

def group_anagrams(words):
    groups = {}
    for w in words:
        key = "".join(sorted(w))
        groups.setdefault(key, []).append(w)
    return list(groups.values())

class Solution {
    public List<List<String>> groupAnagrams(String[] words) {
        Map<String, List<String>> groups = new HashMap<>();
        for (String w : words) {
            char[] c = w.toCharArray();
            Arrays.sort(c);
            groups.computeIfAbsent(new String(c), x -> new ArrayList<>()).add(w);
        }
        return new ArrayList<>(groups.values());
    }
}

from collections import Counter

def top_k_frequent(nums, k):
    count = Counter(nums)
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, c in count.items():
        buckets[c].append(x)
    res = []
    for c in range(len(nums), 0, -1):
        for x in buckets[c]:
            res.append(x)
            if len(res) == k:
                return res
    return res

class Solution {
    public int[] topKFrequent(int[] nums, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int x : nums) count.merge(x, 1, Integer::sum);
        List<List<Integer>> buckets = new ArrayList<>();
        for (int i = 0; i <= nums.length; i++) buckets.add(new ArrayList<>());
        count.forEach((x, c) -> buckets.get(c).add(x));
        int[] res = new int[k];
        int n = 0;
        for (int c = nums.length; c > 0 && n < k; c--)
            for (int x : buckets.get(c)) if (n < k) res[n++] = x;
        return res;
    }
}

class Solution {
    public int[] productExceptSelf(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        for (int i = 0, left = 1; i < n; left *= nums[i++]) res[i] = left;
        for (int i = n - 1, right = 1; i >= 0; right *= nums[i--]) res[i] *= right;
        return res;
    }
}

def longest_run(nums):
    s, best = set(nums), 0
    for x in s:
        if x - 1 not in s:
            length = 1
            while x + length in s:
                length += 1
            best = max(best, length)
    return best

class Solution {
    public int longestRun(int[] nums) {
        Set<Integer> s = new HashSet<>();
        for (int x : nums) s.add(x);
        int best = 0;
        for (int x : s) {
            if (s.contains(x - 1)) continue;
            int length = 1;
            while (s.contains(x + length)) length++;
            best = Math.max(best, length);
        }
        return best;
    }
}

def majority(nums):
    candidate, votes = None, 0
    for i, x in enumerate(nums):
        if votes == 0:
            candidate = x
        votes += 1 if x == candidate else -1
    return candidate

class Solution {
    public int majority(int[] nums) {
        int candidate = 0, votes = 0;
        for (int x : nums) {
            if (votes == 0) candidate = x;
            votes += x == candidate ? 1 : -1;
        }
        return candidate;
    }
}

from collections import Counter

def first_unique(s):
    count = Counter(s)
    for i, ch in enumerate(s):
        if count[ch] == 1:
            return i
    return -1

class Solution {
    public int firstUnique(String s) {
        int[] count = new int[26];
        for (char c : s.toCharArray()) count[c - 'a']++;
        for (int i = 0; i < s.length(); i++)
            if (count[s.charAt(i) - 'a'] == 1) return i;
        return -1;
    }
}

def same_shape(s, t):
    fwd, back = {}, {}
    for i, (a, b) in enumerate(zip(s, t)):
        if fwd.get(a, b) != b or back.get(b, a) != a:
            return False
        fwd[a], back[b] = b, a
    return True

class Solution {
    public boolean sameShape(String s, String t) {
        Map<Character, Character> fwd = new HashMap<>(), back = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (fwd.getOrDefault(a, b) != b || back.getOrDefault(b, a) != a) return false;
            fwd.put(a, b); back.put(b, a);
        }
        return true;
    }
}

def can_build(note, magazine):
    count = [0] * 26
    for ch in magazine:
        count[ord(ch) - 97] += 1
    for ch in note:
        count[ord(ch) - 97] -= 1
        if count[ord(ch) - 97] < 0:
            return False
    return True

class Solution {
    public boolean canBuild(String note, String magazine) {
        int[] count = new int[26];
        for (char c : magazine.toCharArray()) count[c - 'a']++;
        for (char c : note.toCharArray()) {
            count[c - 'a']--;
            if (count[c - 'a'] < 0) return false;
        }
        return true;
    }
}

def first_missing_positive(nums):
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            j = nums[i] - 1
            nums[i], nums[j] = nums[j], nums[i]
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1
    return n + 1

class Solution {
    public int firstMissingPositive(int[] nums) {
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                int j = nums[i] - 1, t = nums[j]; nums[j] = nums[i]; nums[i] = t;
            }
        }
        for (int i = 0; i < n; i++) if (nums[i] != i + 1) return i + 1;
        return n + 1;
    }
}

class RangeSum:
    def __init__(self, nums):
        self.prefix = [0]
        for x in nums:
            self.prefix.append(self.prefix[-1] + x)

    def query(self, l, r):
        return self.prefix[r + 1] - self.prefix[l]

class RangeSum {
    private final int[] prefix;

    RangeSum(int[] nums) {
        prefix = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) prefix[i + 1] = prefix[i] + nums[i];
    }

    public int query(int l, int r) {
        return prefix[r + 1] - prefix[l];
    }
}

class Solution {
    public int countSumK(int[] nums, int k) {
        Map<Integer, Integer> seen = new HashMap<>();
        seen.put(0, 1);
        int prefix = 0, count = 0;
        for (int x : nums) {
            prefix += x;
            count += seen.getOrDefault(prefix - k, 0);
            seen.merge(prefix, 1, Integer::sum);
        }
        return count;
    }
}

def balance_index(nums):
    total, left = sum(nums), 0
    for i, x in enumerate(nums):
        if left == total - left - x:
            return i
        left += x
    return -1

class Solution {
    public int balanceIndex(int[] nums) {
        int total = 0, left = 0;
        for (int x : nums) total += x;
        for (int i = 0; i < nums.length; i++) {
            if (left == total - left - nums[i]) return i;
            left += nums[i];
        }
        return -1;
    }
}

def longest_equal(nums):
    first, bal, best = {0: -1}, 0, 0
    for i, x in enumerate(nums):
        bal += 1 if x == 1 else -1
        if bal in first:
            best = max(best, i - first[bal])
        else:
            first[bal] = i
    return best

class Solution {
    public int longestEqual(int[] nums) {
        Map<Integer, Integer> first = new HashMap<>();
        first.put(0, -1);
        int bal = 0, best = 0;
        for (int i = 0; i < nums.length; i++) {
            bal += nums[i] == 1 ? 1 : -1;
            if (first.containsKey(bal)) best = Math.max(best, i - first.get(bal));
            else first.put(bal, i);
        }
        return best;
    }
}

class Solution {
    public int divisibleRuns(int[] nums, int k) {
        int[] seen = new int[k];
        seen[0] = 1;
        int rem = 0, count = 0;
        for (int x : nums) {
            rem = ((rem + x) % k + k) % k;
            count += seen[rem]++;
        }
        return count;
    }
}

def seat_totals(bookings, n):
    diff = [0] * (n + 1)
    for first, last, seats in bookings:
        diff[first - 1] += seats
        diff[last] -= seats
    res, running = [], 0
    for i in range(n):
        running += diff[i]
        res.append(running)
    return res

class Solution {
    public int[] seatTotals(int[][] bookings, int n) {
        int[] diff = new int[n + 1];
        for (int[] b : bookings) { diff[b[0] - 1] += b[2]; diff[b[1]] -= b[2]; }
        int[] res = new int[n];
        for (int i = 0, running = 0; i < n; i++) res[i] = running += diff[i];
        return res;
    }
}

def search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

class Solution {
    public int search(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }
}

def insert_position(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid
    return lo

class Solution {
    public int insertPosition(int[] nums, int target) {
        int lo = 0, hi = nums.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

def first_and_last(nums, target):
    def lower(x):
        lo, hi = 0, len(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] < x:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower(target)
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, lower(target + 1) - 1]

class Solution {
    public int[] firstAndLast(int[] nums, int target) {
        int first = lower(nums, target);
        if (first == nums.length || nums[first] != target) return new int[]{-1, -1};
        return new int[]{first, lower(nums, target + 1) - 1};
    }

    private int lower(int[] nums, int x) {
        int lo = 0, hi = nums.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] < x) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
}

def rotated_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

class Solution {
    public int rotatedSearch(int[] nums, int target) {
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] == target) return mid;
            if (nums[lo] <= nums[mid]) {
                if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {
                if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }
}

def rotated_min(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1
        else:
            hi = mid
    return nums[lo]

class Solution {
    public int rotatedMin(int[] nums) {
        int lo = 0, hi = nums.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] > nums[hi]) lo = mid + 1;
            else hi = mid;
        }
        return nums[lo];
    }
}

def int_sqrt(x):
    lo, hi = 0, x
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if mid * mid <= x:
            lo = mid
        else:
            hi = mid - 1
    return lo

class Solution {
    public int intSqrt(int x) {
        long lo = 0, hi = x;
        while (lo < hi) {
            long mid = (lo + hi + 1) / 2;
            if (mid * mid <= x) lo = mid;
            else hi = mid - 1;
        }
        return (int) lo;
    }
}

def min_speed(piles, h):
    lo, hi = 1, max(piles)
    while lo < hi:
        k = (lo + hi) // 2
        hours = sum((p + k - 1) // k for p in piles)
        if hours <= h:
            hi = k
        else:
            lo = k + 1
    return lo

class Solution {
    public int minSpeed(int[] piles, int h) {
        int lo = 1, hi = 0;
        for (int p : piles) hi = Math.max(hi, p);
        while (lo < hi) {
            int k = lo + (hi - lo) / 2;
            long hours = 0;
            for (int p : piles) hours += (p + k - 1) / k;
            if (hours <= h) hi = k;
            else lo = k + 1;
        }
        return lo;
    }
}

def min_capacity(weights, days):
    lo, hi = max(weights), sum(weights)
    while lo < hi:
        cap = (lo + hi) // 2
        need, load = 1, 0
        for w in weights:
            if load + w > cap:
                need, load = need + 1, 0
            load += w
        if need <= days:
            hi = cap
        else:
            lo = cap + 1
    return lo

class Solution {
    public int minCapacity(int[] weights, int days) {
        int lo = 0, hi = 0;
        for (int w : weights) { lo = Math.max(lo, w); hi += w; }
        while (lo < hi) {
            int cap = (lo + hi) >>> 1, need = 1, load = 0;
            for (int w : weights) {
                if (load + w > cap) { need++; load = 0; }
                load += w;
            }
            if (need <= days) hi = cap;
            else lo = cap + 1;
        }
        return lo;
    }
}

def find_peak(nums):
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    return lo

class Solution {
    public int findPeak(int[] nums) {
        int lo = 0, hi = nums.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (nums[mid] < nums[mid + 1]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

def search_grid(grid, target):
    m, n = len(grid), len(grid[0])
    lo, hi = 0, m * n - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        val = grid[mid // n][mid % n]
        if val == target:
            return True
        if val < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return False

class Solution {
    public boolean searchGrid(int[][] grid, int target) {
        int m = grid.length, n = grid[0].length, lo = 0, hi = m * n - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1, val = grid[mid / n][mid % n];
            if (val == target) return true;
            if (val < target) lo = mid + 1; else hi = mid - 1;
        }
        return false;
    }
}

def brackets_match(s):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for i, ch in enumerate(s):
        if ch not in pairs:
            stack.append(ch)
        elif stack and stack[-1] == pairs[ch]:
            stack.pop()
        else:
            return False
    return not stack

class Solution {
    public boolean bracketsMatch(String s) {
        Deque<Character> stack = new ArrayDeque<>();
        for (char ch : s.toCharArray()) {
            char open = ch == ')' ? '(' : ch == ']' ? '[' : '{';
            if (ch == '(' || ch == '[' || ch == '{') stack.push(ch);
            else if (!stack.isEmpty() && stack.peek() == open) stack.pop();
            else return false;
        }
        return stack.isEmpty();
    }
}

class MinStack:
    def __init__(self):
        self.stack = []

    def push(self, x):
        low = min(x, self.stack[-1][1]) if self.stack else x
        self.stack.append((x, low))

    def pop(self):
        self.stack.pop()

    def top(self):
        return self.stack[-1][0]

    def getMin(self):
        return self.stack[-1][1]

class MinStack {
    private final Deque<int[]> stack = new ArrayDeque<>();

    public void push(int x) {
        stack.push(new int[]{x, stack.isEmpty() ? x : Math.min(x, stack.peek()[1])});
    }

    public void pop() { stack.pop(); }

    public int top() { return stack.peek()[0]; }

    public int getMin() { return stack.peek()[1]; }
}

def postfix(tokens):
    ops = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
           "*": lambda a, b: a * b, "/": lambda a, b: int(a / b)}
    stack = []
    for i, t in enumerate(tokens):
        if t in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[t](a, b))
        else:
            stack.append(int(t))
    return stack[0]

class Solution {
    public int postfix(String[] tokens) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (String t : tokens) {
            if ("+-*/".contains(t) && t.length() == 1) {
                int b = stack.pop(), a = stack.pop();
                stack.push(t.equals("+") ? a + b : t.equals("-") ? a - b : t.equals("*") ? a * b : a / b);
            } else stack.push(Integer.parseInt(t));
        }
        return stack.pop();
    }
}

def days_until_warmer(temps):
    res, stack = [0] * len(temps), []
    for i, t in enumerate(temps):
        while stack and temps[stack[-1]] < t:
            j = stack.pop()
            res[j] = i - j
        stack.append(i)
    return res

class Solution {
    public int[] daysUntilWarmer(int[] temps) {
        int[] res = new int[temps.length];
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < temps.length; i++) {
            while (!stack.isEmpty() && temps[stack.peek()] < temps[i]) {
                int j = stack.pop();
                res[j] = i - j;
            }
            stack.push(i);
        }
        return res;
    }
}

def next_greater_circular(nums):
    n = len(nums)
    res, stack = [-1] * n, []
    for i in range(2 * n):
        x = nums[i % n]
        while stack and nums[stack[-1]] < x:
            res[stack.pop()] = x
        if i < n:
            stack.append(i)
    return res

class Solution {
    public int[] nextGreaterCircular(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        Arrays.fill(res, -1);
        Deque<Integer> stack = new ArrayDeque<>();
        for (int i = 0; i < 2 * n; i++) {
            int x = nums[i % n];
            while (!stack.isEmpty() && nums[stack.peek()] < x) res[stack.pop()] = x;
            if (i < n) stack.push(i);
        }
        return res;
    }
}

def largest_rectangle(heights):
    stack, best = [], 0
    for i, h in enumerate(heights + [0]):
        while stack and heights[stack[-1]] >= h:
            top = stack.pop()
            width = i if not stack else i - stack[-1] - 1
            best = max(best, heights[top] * width)
        stack.append(i)
    return best

class Solution {
    public int largestRectangle(int[] heights) {
        Deque<Integer> stack = new ArrayDeque<>();
        int best = 0, n = heights.length;
        for (int i = 0; i <= n; i++) {
            int h = i == n ? 0 : heights[i];
            while (!stack.isEmpty() && heights[stack.peek()] >= h) {
                int top = stack.pop();
                int width = stack.isEmpty() ? i : i - stack.peek() - 1;
                best = Math.max(best, heights[top] * width);
            }
            stack.push(i);
        }
        return best;
    }
}

def expand(s):
    stack, cur, num = [], "", 0
    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == "[":
            stack.append((cur, num))
            cur, num = "", 0
        elif ch == "]":
            prev, k = stack.pop()
            cur = prev + cur * k
        else:
            cur += ch
    return cur

class Solution {
    public String expand(String s) {
        Deque<Object[]> stack = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        int num = 0;
        for (char ch : s.toCharArray()) {
            if (Character.isDigit(ch)) num = num * 10 + (ch - '0');
            else if (ch == '[') { stack.push(new Object[]{cur, num}); cur = new StringBuilder(); num = 0; }
            else if (ch == ']') {
                Object[] top = stack.pop();
                StringBuilder prev = (StringBuilder) top[0];
                prev.append(cur.toString().repeat((Integer) top[1]));
                cur = prev;
            } else cur.append(ch);
        }
        return cur.toString();
    }
}

def collapse(s):
    res, w = list(s), 0
    for ch in s:
        if w > 0 and res[w - 1] == ch:
            w -= 1
        else:
            res[w] = ch
            w += 1
    return "".join(res[:w])

class Solution {
    public String collapse(String s) {
        char[] res = s.toCharArray();
        int w = 0;
        for (char ch : s.toCharArray()) {
            if (w > 0 && res[w - 1] == ch) w--;
            else res[w++] = ch;
        }
        return new String(res, 0, w);
    }
}

def collapse(s):
    stack = []
    for i, ch in enumerate(s):
        if stack and stack[-1] == ch:
            stack.pop()
        else:
            stack.append(ch)
    return "".join(stack)

class Solution {
    public String collapse(String s) {
        StringBuilder stack = new StringBuilder();
        for (char ch : s.toCharArray()) {
            int n = stack.length();
            if (n > 0 && stack.charAt(n - 1) == ch) stack.deleteCharAt(n - 1);
            else stack.append(ch);
        }
        return stack.toString();
    }
}

def tidy_path(path):
    stack = []
    for part in path.split("/"):
        if part == "..":
            if stack:
                stack.pop()
        elif part and part != ".":
            stack.append(part)
    return "/" + "/".join(stack)

class Solution {
    public String tidyPath(String path) {
        Deque<String> stack = new ArrayDeque<>();
        for (String part : path.split("/")) {
            if (part.equals("..")) { if (!stack.isEmpty()) stack.pollLast(); }
            else if (!part.isEmpty() && !part.equals(".")) stack.addLast(part);
        }
        return "/" + String.join("/", stack);
    }
}

def collide(rocks):
    stack = []
    for i, r in enumerate(rocks):
        alive = True
        while alive and r < 0 and stack and stack[-1] > 0:
            if stack[-1] < -r:
                stack.pop()
                continue
            if stack[-1] == -r:
                stack.pop()
            alive = False
        if alive:
            stack.append(r)
    return stack

class Solution {
    public int[] collide(int[] rocks) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int r : rocks) {
            boolean alive = true;
            while (alive && r < 0 && !stack.isEmpty() && stack.peekLast() > 0) {
                if (stack.peekLast() < -r) { stack.pollLast(); continue; }
                if (stack.peekLast() == -r) stack.pollLast();
                alive = false;
            }
            if (alive) stack.addLast(r);
        }
        return stack.stream().mapToInt(Integer::intValue).toArray();
    }
}

def convoys(target, position, speed):
    stack = []
    for p, s in sorted(zip(position, speed), reverse=True):
        t = (target - p) / s
        if not stack or t > stack[-1]:
            stack.append(t)
    return len(stack)

class Solution {
    public int convoys(int target, int[] position, int[] speed) {
        int n = position.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a, b) -> position[b] - position[a]);
        Deque<Double> stack = new ArrayDeque<>();
        for (int i : idx) {
            double t = (double) (target - position[i]) / speed[i];
            if (stack.isEmpty() || t > stack.peek()) stack.push(t);
        }
        return stack.size();
    }
}

class Solution {
    public ListNode reverseList(ListNode head) {
        ListNode prev = null, cur = head;
        while (cur != null) {
            ListNode nxt = cur.next;
            cur.next = prev;
            prev = cur; cur = nxt;
        }
        return prev;
    }
}

def merge_lists(a, b):
    dummy = tail = ListNode()
    while a and b:
        if a.val <= b.val:
            tail.next, a = a, a.next
        else:
            tail.next, b = b, b.next
        tail = tail.next
    tail.next = a or b
    return dummy.next

class Solution {
    public ListNode mergeLists(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(), tail = dummy;
        while (a != null && b != null) {
            if (a.val <= b.val) { tail.next = a; a = a.next; }
            else { tail.next = b; b = b.next; }
            tail = tail.next;
        }
        tail.next = a != null ? a : b;
        return dummy.next;
    }
}

def has_loop(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            return True
    return False

class Solution {
    public boolean hasLoop(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next; fast = fast.next.next;
            if (slow == fast) return true;
        }
        return false;
    }
}

def loop_entrance(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
        if slow is fast:
            slow = head
            while slow is not fast:
                slow, fast = slow.next, fast.next
            return slow
    return None

class Solution {
    public ListNode loopEntrance(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next; fast = fast.next.next;
            if (slow == fast) {
                slow = head;
                while (slow != fast) { slow = slow.next; fast = fast.next; }
                return slow;
            }
        }
        return null;
    }
}

def middle(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    return slow

class Solution {
    public ListNode middle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; }
        return slow;
    }
}

def remove_kth_from_end(head, k):
    dummy = ListNode(0, head)
    slow = fast = dummy
    for _ in range(k):
        fast = fast.next
    while fast.next:
        slow, fast = slow.next, fast.next
    slow.next = slow.next.next
    return dummy.next

class Solution {
    public ListNode removeKthFromEnd(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head), slow = dummy, fast = dummy;
        for (int i = 0; i < k; i++) fast = fast.next;
        while (fast.next != null) { slow = slow.next; fast = fast.next; }
        slow.next = slow.next.next;
        return dummy.next;
    }
}

def is_palindrome_chain(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    prev = None
    while slow:
        slow.next, prev, slow = prev, slow, slow.next
    left, right = head, prev
    while right:
        if left.val != right.val:
            return False
        left, right = left.next, right.next
    return True

class Solution {
    public boolean isPalindromeChain(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; }
        ListNode prev = null;
        while (slow != null) { ListNode n = slow.next; slow.next = prev; prev = slow; slow = n; }
        ListNode left = head, right = prev;
        while (right != null) {
            if (left.val != right.val) return false;
            left = left.next; right = right.next;
        }
        return true;
    }
}

def weave(head):
    slow = fast = head
    while fast and fast.next:
        slow, fast = slow.next, fast.next.next
    prev, cur = None, slow.next
    slow.next = None
    while cur:
        cur.next, prev, cur = prev, cur, cur.next
    a, b = head, prev
    while b:
        a.next, b.next, a, b = b, a.next, a.next, b.next

class Solution {
    public void weave(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) { slow = slow.next; fast = fast.next.next; }
        ListNode prev = null, cur = slow.next;
        slow.next = null;
        while (cur != null) { ListNode n = cur.next; cur.next = prev; prev = cur; cur = n; }
        ListNode a = head, b = prev;
        while (b != null) {
            ListNode an = a.next, bn = b.next;
            a.next = b; b.next = an; a = an; b = bn;
        }
    }
}

class Solution {
    public ListNode addChains(ListNode a, ListNode b) {
        ListNode dummy = new ListNode(), tail = dummy;
        int carry = 0;
        while (a != null || b != null || carry > 0) {
            int total = carry + (a != null ? a.val : 0) + (b != null ? b.val : 0);
            carry = total / 10;
            tail.next = new ListNode(total % 10);
            tail = tail.next;
            a = a != null ? a.next : null;
            b = b != null ? b.next : null;
        }
        return dummy.next;
    }
}

def dedupe_chain(head):
    cur = head
    while cur and cur.next:
        if cur.next.val == cur.val:
            cur.next = cur.next.next
        else:
            cur = cur.next
    return head

class Solution {
    public ListNode dedupeChain(ListNode head) {
        ListNode cur = head;
        while (cur != null && cur.next != null) {
            if (cur.next.val == cur.val) cur.next = cur.next.next;
            else cur = cur.next;
        }
        return head;
    }
}

class Solution {
    public ListNode oddEven(ListNode head) {
        if (head == null) return head;
        ListNode odd = head, even = head.next, evenHead = even;
        while (even != null && even.next != null) {
            odd.next = even.next; odd = odd.next;
            even.next = odd.next; even = even.next;
        }
        odd.next = evenHead;
        return head;
    }
}

class Solution {
    public ListNode rotateChain(ListNode head, int k) {
        if (head == null) return head;
        int n = 1;
        ListNode tail = head;
        while (tail.next != null) { tail = tail.next; n++; }
        k %= n;
        tail.next = head;
        ListNode newTail = head;
        for (int i = 0; i < n - k - 1; i++) newTail = newTail.next;
        ListNode newHead = newTail.next;
        newTail.next = null;
        return newHead;
    }
}

class Solution {
    public ListNode swapPairs(ListNode head) {
        ListNode dummy = new ListNode(0, head), prev = dummy;
        while (prev.next != null && prev.next.next != null) {
            ListNode a = prev.next, b = a.next;
            prev.next = b; a.next = b.next; b.next = a;
            prev = a;
        }
        return dummy.next;
    }
}

def reverse_groups(head, k):
    dummy = ListNode(0, head)
    group_prev = dummy
    while True:
        kth = group_prev
        for _ in range(k):
            kth = kth.next
            if not kth:
                return dummy.next
        group_next = kth.next
        prev, cur = group_next, group_prev.next
        while cur is not group_next:
            cur.next, prev, cur = prev, cur, cur.next
        first = group_prev.next
        group_prev.next = prev
        group_prev = first

class Solution {
    public ListNode reverseGroups(ListNode head, int k) {
        ListNode dummy = new ListNode(0, head), groupPrev = dummy;
        while (true) {
            ListNode kth = groupPrev;
            for (int i = 0; i < k; i++) { kth = kth.next; if (kth == null) return dummy.next; }
            ListNode groupNext = kth.next, prev = groupNext, cur = groupPrev.next;
            while (cur != groupNext) { ListNode n = cur.next; cur.next = prev; prev = cur; cur = n; }
            ListNode first = groupPrev.next;
            groupPrev.next = prev;
            groupPrev = first;
        }
    }
}

def max_depth(root):
    if not root:
        return 0
    left, right = max_depth(root.left), max_depth(root.right)
    return 1 + max(left, right)

class Solution {
    public int maxDepth(TreeNode root) {
        if (root == null) return 0;
        return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));
    }
}

def mirror(root):
    if root:
        root.left, root.right = mirror(root.right), mirror(root.left)
    return root

class Solution {
    public TreeNode mirror(TreeNode root) {
        if (root == null) return null;
        TreeNode l = mirror(root.left);
        root.left = mirror(root.right);
        root.right = l;
        return root;
    }
}

def same_tree(a, b):
    if not a or not b:
        return a is b
    return a.val == b.val and same_tree(a.left, b.left) and same_tree(a.right, b.right)

class Solution {
    public boolean sameTree(TreeNode a, TreeNode b) {
        if (a == null || b == null) return a == b;
        return a.val == b.val && sameTree(a.left, b.left) && sameTree(a.right, b.right);
    }
}

def is_symmetric(root):
    def mirror(a, b):
        if not a or not b:
            return a is b
        return a.val == b.val and mirror(a.left, b.right) and mirror(a.right, b.left)
    return mirror(root.left, root.right)

class Solution {
    public boolean isSymmetric(TreeNode root) {
        return mirror(root.left, root.right);
    }

    private boolean mirror(TreeNode a, TreeNode b) {
        if (a == null || b == null) return a == b;
        return a.val == b.val && mirror(a.left, b.right) && mirror(a.right, b.left);
    }
}

class Solution {
    public List<List<Integer>> levels(TreeNode root) {
        List<List<Integer>> res = new ArrayList<>();
        Deque<TreeNode> q = new ArrayDeque<>();
        if (root != null) q.add(root);
        while (!q.isEmpty()) {
            List<Integer> level = new ArrayList<>();
            for (int n = q.size(); n > 0; n--) {
                TreeNode node = q.poll();
                level.add(node.val);
                if (node.left != null) q.add(node.left);
                if (node.right != null) q.add(node.right);
            }
            res.add(level);
        }
        return res;
    }
}

def is_valid_bst(root, lo=float("-inf"), hi=float("inf")):
    if not root:
        return True
    if not lo < root.val < hi:
        return False
    return is_valid_bst(root.left, lo, root.val) and is_valid_bst(root.right, root.val, hi)

class Solution {
    public boolean isValidBst(TreeNode root) {
        return valid(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }

    private boolean valid(TreeNode node, long lo, long hi) {
        if (node == null) return true;
        if (node.val <= lo || node.val >= hi) return false;
        return valid(node.left, lo, node.val) && valid(node.right, node.val, hi);
    }
}

def common_ancestor(root, p, q):
    node = root
    while True:
        if p < node.val and q < node.val:
            node = node.left
        elif p > node.val and q > node.val:
            node = node.right
        else:
            return node.val

class Solution {
    public int commonAncestor(TreeNode root, int p, int q) {
        TreeNode node = root;
        while (true) {
            if (p < node.val && q < node.val) node = node.left;
            else if (p > node.val && q > node.val) node = node.right;
            else return node.val;
        }
    }
}

def kth_smallest(root, k):
    stack, node = [], root
    while True:
        while node:
            stack.append(node)
            node = node.left
        node = stack.pop()
        k -= 1
        if k == 0:
            return node.val
        node = node.right

class Solution {
    public int kthSmallest(TreeNode root, int k) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode node = root;
        while (true) {
            for (; node != null; node = node.left) stack.push(node);
            node = stack.pop();
            if (--k == 0) return node.val;
            node = node.right;
        }
    }
}

def diameter(root):
    best = 0

    def depth(node):
        nonlocal best
        if not node:
            return 0
        left, right = depth(node.left), depth(node.right)
        best = max(best, left + right)
        return 1 + max(left, right)

    depth(root)
    return best

class Solution {
    private int best = 0;

    public int diameter(TreeNode root) {
        depth(root);
        return best;
    }

    private int depth(TreeNode node) {
        if (node == null) return 0;
        int left = depth(node.left), right = depth(node.right);
        best = Math.max(best, left + right);
        return 1 + Math.max(left, right);
    }
}

def is_balanced(root):
    def height(node):
        if not node:
            return 0
        left, right = height(node.left), height(node.right)
        if left < 0 or right < 0 or abs(left - right) > 1:
            return -1
        return 1 + max(left, right)

    return height(root) >= 0

class Solution {
    public boolean isBalanced(TreeNode root) {
        return height(root) >= 0;
    }

    private int height(TreeNode node) {
        if (node == null) return 0;
        int left = height(node.left), right = height(node.right);
        if (left < 0 || right < 0 || Math.abs(left - right) > 1) return -1;
        return 1 + Math.max(left, right);
    }
}

from collections import deque

def right_view(root):
    res, q = [], deque([root] if root else [])
    while q:
        for i in range(len(q)):
            node = q.popleft()
            q.extend(c for c in (node.left, node.right) if c)
        res.append(node.val)
    return res

class Solution {
    public List<Integer> rightView(TreeNode root) {
        List<Integer> res = new ArrayList<>();
        Deque<TreeNode> q = new ArrayDeque<>();
        if (root != null) q.add(root);
        while (!q.isEmpty()) {
            TreeNode node = null;
            for (int n = q.size(); n > 0; n--) {
                node = q.poll();
                if (node.left != null) q.add(node.left);
                if (node.right != null) q.add(node.right);
            }
            res.add(node.val);
        }
        return res;
    }
}

def has_path_sum(root, target):
    if not root:
        return False
    target -= root.val
    if not root.left and not root.right:
        return target == 0
    return has_path_sum(root.left, target) or has_path_sum(root.right, target)

class Solution {
    public boolean hasPathSum(TreeNode root, int target) {
        if (root == null) return false;
        target -= root.val;
        if (root.left == null && root.right == null) return target == 0;
        return hasPathSum(root.left, target) || hasPathSum(root.right, target);
    }
}

def bst_pair_sum(root, k):
    vals = []

    def inorder(node):
        if node:
            inorder(node.left)
            vals.append(node.val)
            inorder(node.right)

    inorder(root)
    left, right = 0, len(vals) - 1
    while left < right:
        s = vals[left] + vals[right]
        if s == k:
            return True
        if s < k:
            left += 1
        else:
            right -= 1
    return False

class Solution {
    public boolean bstPairSum(TreeNode root, int k) {
        List<Integer> vals = new ArrayList<>();
        inorder(root, vals);
        int left = 0, right = vals.size() - 1;
        while (left < right) {
            int s = vals.get(left) + vals.get(right);
            if (s == k) return true;
            if (s < k) left++;
            else right--;
        }
        return false;
    }

    private void inorder(TreeNode node, List<Integer> vals) {
        if (node == null) return;
        inorder(node.left, vals);
        vals.add(node.val);
        inorder(node.right, vals);
    }
}

def rebuild(preorder, inorder):
    pos = {v: i for i, v in enumerate(inorder)}
    it = iter(preorder)

    def build(lo, hi):
        if lo > hi:
            return None
        val = next(it)
        node = TreeNode(val)
        node.left = build(lo, pos[val] - 1)
        node.right = build(pos[val] + 1, hi)
        return node

    return build(0, len(inorder) - 1)

class Solution {
    private int next = 0;

    public TreeNode rebuild(int[] preorder, int[] inorder) {
        Map<Integer, Integer> pos = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) pos.put(inorder[i], i);
        return build(preorder, pos, 0, inorder.length - 1);
    }

    private TreeNode build(int[] pre, Map<Integer, Integer> pos, int lo, int hi) {
        if (lo > hi) return null;
        TreeNode node = new TreeNode(pre[next++]);
        node.left = build(pre, pos, lo, pos.get(node.val) - 1);
        node.right = build(pre, pos, pos.get(node.val) + 1, hi);
        return node;
    }
}

def max_path_sum(root):
    best = root.val

    def gain(node):
        nonlocal best
        if not node:
            return 0
        left, right = max(gain(node.left), 0), max(gain(node.right), 0)
        best = max(best, node.val + left + right)
        return node.val + max(left, right)

    gain(root)
    return best

class Solution {
    private int best;

    public int maxPathSum(TreeNode root) {
        best = root.val;
        gain(root);
        return best;
    }

    private int gain(TreeNode node) {
        if (node == null) return 0;
        int left = Math.max(gain(node.left), 0), right = Math.max(gain(node.right), 0);
        best = Math.max(best, node.val + left + right);
        return node.val + Math.max(left, right);
    }
}

def good_nodes(root, high=float("-inf")):
    if not root:
        return 0
    good = 1 if root.val >= high else 0
    high = max(high, root.val)
    return good + good_nodes(root.left, high) + good_nodes(root.right, high)

class Solution {
    public int goodNodes(TreeNode root) {
        return count(root, Integer.MIN_VALUE);
    }

    private int count(TreeNode node, int high) {
        if (node == null) return 0;
        int good = node.val >= high ? 1 : 0;
        high = Math.max(high, node.val);
        return good + count(node.left, high) + count(node.right, high);
    }
}

def to_bst(nums):
    def build(lo, hi):
        if lo > hi:
            return None
        mid = (lo + hi) // 2
        node = TreeNode(nums[mid])
        node.left, node.right = build(lo, mid - 1), build(mid + 1, hi)
        return node

    return build(0, len(nums) - 1)

class Solution {
    public TreeNode toBst(int[] nums) {
        return build(nums, 0, nums.length - 1);
    }

    private TreeNode build(int[] nums, int lo, int hi) {
        if (lo > hi) return null;
        int mid = (lo + hi) >>> 1;
        TreeNode node = new TreeNode(nums[mid]);
        node.left = build(nums, lo, mid - 1);
        node.right = build(nums, mid + 1, hi);
        return node;
    }
}

import heapq

def kth_largest(nums, k):
    heap = []
    for i, x in enumerate(nums):
        heapq.heappush(heap, x)
        if len(heap) > k:
            heapq.heappop(heap)
    return heap[0]

class Solution {
    public int kthLargest(int[] nums, int k) {
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int x : nums) {
            heap.add(x);
            if (heap.size() > k) heap.poll();
        }
        return heap.peek();
    }
}

import heapq

def last_stone(stones):
    heap = [-s for s in stones]
    heapq.heapify(heap)
    while len(heap) > 1:
        y, x = -heapq.heappop(heap), -heapq.heappop(heap)
        if y != x:
            heapq.heappush(heap, x - y)
    return -heap[0] if heap else 0

class Solution {
    public int lastStone(int[] stones) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int s : stones) heap.add(s);
        while (heap.size() > 1) {
            int y = heap.poll(), x = heap.poll();
            if (y != x) heap.add(y - x);
        }
        return heap.isEmpty() ? 0 : heap.peek();
    }
}

import heapq

def k_closest(points, k):
    heap = []
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)
    return [[x, y] for _, x, y in heap]

class Solution {
    public int[][] kClosest(int[][] points, int k) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> (b[0] * b[0] + b[1] * b[1]) - (a[0] * a[0] + a[1] * a[1]));
        for (int[] p : points) {
            heap.add(p);
            if (heap.size() > k) heap.poll();
        }
        return heap.toArray(new int[0][]);
    }
}

class Solution {
    public ListNode mergeK(ListNode[] lists) {
        PriorityQueue<ListNode> heap = new PriorityQueue<>((a, b) -> a.val - b.val);
        for (ListNode n : lists) if (n != null) heap.add(n);
        ListNode dummy = new ListNode(), tail = dummy;
        while (!heap.isEmpty()) {
            ListNode node = heap.poll();
            tail.next = node;
            tail = node;
            if (node.next != null) heap.add(node.next);
        }
        return dummy.next;
    }
}

import heapq

class MedianFinder:
    def __init__(self):
        self.small, self.large = [], []

    def addNum(self, x):
        heapq.heappush(self.small, -x)
        heapq.heappush(self.large, -heapq.heappop(self.small))
        if len(self.large) > len(self.small):
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def findMedian(self):
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2

class MedianFinder {
    private final PriorityQueue<Integer> small = new PriorityQueue<>(Collections.reverseOrder());
    private final PriorityQueue<Integer> large = new PriorityQueue<>();

    public void addNum(int x) {
        small.add(x);
        large.add(small.poll());
        if (large.size() > small.size()) small.add(large.poll());
    }

    public double findMedian() {
        if (small.size() > large.size()) return small.peek();
        return (small.peek() + large.peek()) / 2.0;
    }
}

from collections import Counter

def least_time(tasks, n):
    counts = Counter(tasks).values()
    top = max(counts)
    ties = sum(1 for c in counts if c == top)
    return max(len(tasks), (top - 1) * (n + 1) + ties)

class Solution {
    public int leastTime(char[] tasks, int n) {
        int[] counts = new int[26];
        int top = 0, ties = 0;
        for (char t : tasks) top = Math.max(top, ++counts[t - 'A']);
        for (int c : counts) if (c == top) ties++;
        return Math.max(tasks.length, (top - 1) * (n + 1) + ties);
    }
}

def merge(intervals):
    intervals.sort()
    res = []
    for s, e in intervals:
        if res and s <= res[-1][1]:
            res[-1][1] = max(res[-1][1], e)
        else:
            res.append([s, e])
    return res

class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
        List<int[]> res = new ArrayList<>();
        for (int[] iv : intervals) {
            if (!res.isEmpty() && iv[0] <= res.get(res.size() - 1)[1])
                res.get(res.size() - 1)[1] = Math.max(res.get(res.size() - 1)[1], iv[1]);
            else res.add(new int[]{iv[0], iv[1]});
        }
        return res.toArray(new int[0][]);
    }
}

class Solution {
    public int[][] insert(int[][] intervals, int[] add) {
        List<int[]> res = new ArrayList<>();
        int i = 0, n = intervals.length, start = add[0], end = add[1];
        for (; i < n && intervals[i][1] < start; i++) res.add(intervals[i]);
        for (; i < n && intervals[i][0] <= end; i++) {
            start = Math.min(start, intervals[i][0]);
            end = Math.max(end, intervals[i][1]);
        }
        res.add(new int[]{start, end});
        for (; i < n; i++) res.add(intervals[i]);
        return res.toArray(new int[0][]);
    }
}

def fewest_removals(intervals):
    intervals.sort(key=lambda iv: iv[1])
    last_end, removed = float("-inf"), 0
    for s, e in intervals:
        if s >= last_end:
            last_end = e
        else:
            removed += 1
    return removed

class Solution {
    public int fewestRemovals(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[1], b[1]));
        long lastEnd = Long.MIN_VALUE;
        int removed = 0;
        for (int[] iv : intervals) {
            if (iv[0] >= lastEnd) lastEnd = iv[1];
            else removed++;
        }
        return removed;
    }
}

def can_attend(meetings):
    meetings.sort()
    for i in range(1, len(meetings)):
        if meetings[i][0] < meetings[i - 1][1]:
            return False
    return True

class Solution {
    public boolean canAttend(int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);
        for (int i = 1; i < meetings.length; i++) if (meetings[i][0] < meetings[i - 1][1]) return false;
        return true;
    }
}

def rooms_needed(meetings):
    starts = sorted(m[0] for m in meetings)
    ends = sorted(m[1] for m in meetings)
    rooms = best = j = 0
    for i in range(len(starts)):
        if starts[i] < ends[j]:
            rooms += 1
        else:
            j += 1
        best = max(best, rooms)
    return best

class Solution {
    public int roomsNeeded(int[][] meetings) {
        int n = meetings.length, rooms = 0, best = 0;
        int[] starts = new int[n], ends = new int[n];
        for (int i = 0; i < n; i++) { starts[i] = meetings[i][0]; ends[i] = meetings[i][1]; }
        Arrays.sort(starts);
        Arrays.sort(ends);
        for (int i = 0, j = 0; i < n; i++) {
            if (starts[i] < ends[j]) rooms++;
            else j++;
            best = Math.max(best, rooms);
        }
        return best;
    }
}

def overlaps(a, b):
    res, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        lo, hi = max(a[i][0], b[j][0]), min(a[i][1], b[j][1])
        if lo <= hi:
            res.append([lo, hi])
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

class Solution {
    public int[][] overlaps(int[][] a, int[][] b) {
        List<int[]> res = new ArrayList<>();
        for (int i = 0, j = 0; i < a.length && j < b.length; ) {
            int lo = Math.max(a[i][0], b[j][0]), hi = Math.min(a[i][1], b[j][1]);
            if (lo <= hi) res.add(new int[]{lo, hi});
            if (a[i][1] < b[j][1]) i++; else j++;
        }
        return res.toArray(new int[0][]);
    }
}

def fewest_arrows(points):
    points.sort(key=lambda p: p[1])
    arrows, arrow = 0, float("-inf")
    for s, e in points:
        if s > arrow:
            arrow, arrows = e, arrows + 1
    return arrows

class Solution {
    public int fewestArrows(int[][] points) {
        Arrays.sort(points, (a, b) -> Integer.compare(a[1], b[1]));
        int arrows = 0;
        long arrow = Long.MIN_VALUE;
        for (int[] p : points) if (p[0] > arrow) { arrow = p[1]; arrows++; }
        return arrows;
    }
}

def free_slot(a, b, day_start, day_end, duration):
    i = j = 0
    free_from = day_start
    while i < len(a) or j < len(b):
        if j == len(b) or (i < len(a) and a[i][0] <= b[j][0]):
            s, e = a[i]
            i += 1
        else:
            s, e = b[j]
            j += 1
        if min(s, day_end) - free_from >= duration:
            return [free_from, free_from + duration]
        free_from = max(free_from, e)
    return [free_from, free_from + duration] if day_end - free_from >= duration else []

class Solution {
    public int[] freeSlot(int[][] a, int[][] b, int dayStart, int dayEnd, int duration) {
        int i = 0, j = 0, freeFrom = dayStart;
        while (i < a.length || j < b.length) {
            int[] iv = (j == b.length || (i < a.length && a[i][0] <= b[j][0])) ? a[i++] : b[j++];
            if (Math.min(iv[0], dayEnd) - freeFrom >= duration) return new int[]{freeFrom, freeFrom + duration};
            freeFrom = Math.max(freeFrom, iv[1]);
        }
        return dayEnd - freeFrom >= duration ? new int[]{freeFrom, freeFrom + duration} : new int[0];
    }
}

def count_islands(grid):
    m, n = len(grid), len(grid[0])

    def sink(r, c):
        if 0 <= r < m and 0 <= c < n and grid[r][c] == "1":
            grid[r][c] = "#"
            sink(r + 1, c)
            sink(r - 1, c)
            sink(r, c + 1)
            sink(r, c - 1)

    count = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == "1":
                count += 1
                sink(r, c)
    return count

class Solution {
    public int countIslands(char[][] grid) {
        int count = 0;
        for (int r = 0; r < grid.length; r++)
            for (int c = 0; c < grid[0].length; c++)
                if (grid[r][c] == '1') { count++; sink(grid, r, c); }
        return count;
    }

    private void sink(char[][] g, int r, int c) {
        if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != '1') return;
        g[r][c] = '#';
        sink(g, r + 1, c); sink(g, r - 1, c); sink(g, r, c + 1); sink(g, r, c - 1);
    }
}

def largest_island(grid):
    m, n = len(grid), len(grid[0])

    def area(r, c):
        if not (0 <= r < m and 0 <= c < n) or grid[r][c] != 1:
            return 0
        grid[r][c] = 2
        return 1 + area(r + 1, c) + area(r - 1, c) + area(r, c + 1) + area(r, c - 1)

    best = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                best = max(best, area(r, c))
    return best

class Solution {
    public int largestIsland(int[][] grid) {
        int best = 0;
        for (int r = 0; r < grid.length; r++)
            for (int c = 0; c < grid[0].length; c++)
                if (grid[r][c] == 1) best = Math.max(best, area(grid, r, c));
        return best;
    }

    private int area(int[][] g, int r, int c) {
        if (r < 0 || c < 0 || r >= g.length || c >= g[0].length || g[r][c] != 1) return 0;
        g[r][c] = 2;
        return 1 + area(g, r + 1, c) + area(g, r - 1, c) + area(g, r, c + 1) + area(g, r, c - 1);
    }
}

def paint_fill(image, sr, sc, color):
    old = image[sr][sc]
    if old == color:
        return image

    def fill(r, c):
        if 0 <= r < len(image) and 0 <= c < len(image[0]) and image[r][c] == old:
            image[r][c] = color
            fill(r + 1, c)
            fill(r - 1, c)
            fill(r, c + 1)
            fill(r, c - 1)

    fill(sr, sc)
    return image

class Solution {
    public int[][] paintFill(int[][] image, int sr, int sc, int color) {
        if (image[sr][sc] != color) fill(image, sr, sc, image[sr][sc], color);
        return image;
    }

    private void fill(int[][] img, int r, int c, int old, int color) {
        if (r < 0 || c < 0 || r >= img.length || c >= img[0].length || img[r][c] != old) return;
        img[r][c] = color;
        fill(img, r + 1, c, old, color); fill(img, r - 1, c, old, color);
        fill(img, r, c + 1, old, color); fill(img, r, c - 1, old, color);
    }
}

from collections import deque

def minutes_to_rot(grid):
    m, n = len(grid), len(grid[0])
    q = deque((r, c) for r in range(m) for c in range(n) if grid[r][c] == 2)
    fresh = sum(row.count(1) for row in grid)
    minutes = 0
    while q and fresh:
        for _ in range(len(q)):
            r, c = q.popleft()
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                    grid[nr][nc] = 2
                    fresh -= 1
                    q.append((nr, nc))
        minutes += 1
    return minutes if fresh == 0 else -1

class Solution {
    public int minutesToRot(int[][] grid) {
        int m = grid.length, n = grid[0].length, fresh = 0, minutes = 0;
        Deque<int[]> q = new ArrayDeque<>();
        for (int r = 0; r < m; r++)
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 2) q.add(new int[]{r, c});
                if (grid[r][c] == 1) fresh++;
            }
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!q.isEmpty() && fresh > 0) {
            for (int k = q.size(); k > 0; k--) {
                int[] cell = q.poll();
                for (int[] d : dirs) {
                    int r = cell[0] + d[0], c = cell[1] + d[1];
                    if (r >= 0 && c >= 0 && r < m && c < n && grid[r][c] == 1) {
                        grid[r][c] = 2;
                        fresh--;
                        q.add(new int[]{r, c});
                    }
                }
            }
            minutes++;
        }
        return fresh == 0 ? minutes : -1;
    }
}

class Solution {
    public boolean canFinish(int n, int[][] prereqs) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] p : prereqs) { adj.get(p[1]).add(p[0]); indeg[p[0]]++; }
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) q.add(i);
        int taken = 0;
        while (!q.isEmpty()) {
            int c = q.poll();
            taken++;
            for (int next : adj.get(c)) if (--indeg[next] == 0) q.add(next);
        }
        return taken == n;
    }
}

class Solution {
    public int[] courseOrder(int n, int[][] prereqs) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] p : prereqs) { adj.get(p[1]).add(p[0]); indeg[p[0]]++; }
        PriorityQueue<Integer> heap = new PriorityQueue<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) heap.add(i);
        int[] order = new int[n];
        int k = 0;
        while (!heap.isEmpty()) {
            int c = heap.poll();
            order[k++] = c;
            for (int next : adj.get(c)) if (--indeg[next] == 0) heap.add(next);
        }
        return k == n ? order : new int[0];
    }
}

from collections import deque

def clone(node):
    if not node:
        return None
    copies = {node: Node(node.val)}
    q = deque([node])
    while q:
        cur = q.popleft()
        for nb in cur.neighbors:
            if nb not in copies:
                copies[nb] = Node(nb.val)
                q.append(nb)
            copies[cur].neighbors.append(copies[nb])
    return copies[node]

class Solution {
    public Node clone(Node node) {
        if (node == null) return null;
        Map<Node, Node> copies = new HashMap<>();
        copies.put(node, new Node(node.val));
        Deque<Node> q = new ArrayDeque<>(List.of(node));
        while (!q.isEmpty()) {
            Node cur = q.poll();
            for (Node nb : cur.neighbors) {
                if (!copies.containsKey(nb)) { copies.put(nb, new Node(nb.val)); q.add(nb); }
                copies.get(cur).neighbors.add(copies.get(nb));
            }
        }
        return copies.get(node);
    }
}

from collections import deque

def ladder_length(begin, end, words):
    unseen = set(words)
    queue = deque([(begin, 1)])
    while queue:
        word, steps = queue.popleft()
        if word == end:
            return steps
        for i in range(len(word)):
            for ch in "abcdefghijklmnopqrstuvwxyz":
                nxt = word[:i] + ch + word[i + 1:]
                if nxt in unseen:
                    unseen.remove(nxt)
                    queue.append((nxt, steps + 1))
    return 0

class Solution {
    public int ladderLength(String begin, String end, String[] words) {
        Set<String> unseen = new HashSet<>(Arrays.asList(words));
        Deque<Object[]> q = new ArrayDeque<>();
        q.add(new Object[]{begin, 1});
        while (!q.isEmpty()) {
            Object[] cur = q.poll();
            String word = (String) cur[0];
            int steps = (Integer) cur[1];
            if (word.equals(end)) return steps;
            char[] c = word.toCharArray();
            for (int i = 0; i < c.length; i++) {
                char orig = c[i];
                for (char ch = 'a'; ch <= 'z'; ch++) {
                    c[i] = ch;
                    String next = new String(c);
                    if (unseen.remove(next)) q.add(new Object[]{next, steps + 1});
                }
                c[i] = orig;
            }
        }
        return 0;
    }
}

def redundant_link(edges):
    parent = list(range(len(edges) + 1))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            return [a, b]
        parent[ra] = rb
    return []

class Solution {
    private int[] parent;

    public int[] redundantLink(int[][] edges) {
        parent = new int[edges.length + 1];
        for (int i = 0; i < parent.length; i++) parent[i] = i;
        for (int[] e : edges) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra == rb) return e;
            parent[ra] = rb;
        }
        return new int[0];
    }

    private int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
}

import heapq

def network_delay(times, n, k):
    adj = {}
    for u, v, w in times:
        adj.setdefault(u, []).append((v, w))
    dist, heap = {}, [(0, k)]
    while heap:
        d, u = heapq.heappop(heap)
        if u in dist:
            continue
        dist[u] = d
        for v, w in adj.get(u, []):
            if v not in dist:
                heapq.heappush(heap, (d + w, v))
    return max(dist.values()) if len(dist) == n else -1

class Solution {
    public int networkDelay(int[][] times, int n, int k) {
        Map<Integer, List<int[]>> adj = new HashMap<>();
        for (int[] t : times) adj.computeIfAbsent(t[0], x -> new ArrayList<>()).add(new int[]{t[1], t[2]});
        Map<Integer, Integer> dist = new HashMap<>();
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        heap.add(new int[]{0, k});
        while (!heap.isEmpty()) {
            int[] top = heap.poll();
            if (dist.containsKey(top[1])) continue;
            dist.put(top[1], top[0]);
            for (int[] e : adj.getOrDefault(top[1], List.of()))
                if (!dist.containsKey(e[0])) heap.add(new int[]{top[0] + e[1], e[0]});
        }
        return dist.size() == n ? Collections.max(dist.values()) : -1;
    }
}

def subsets(nums):
    res, path = [], []

    def explore(start):
        res.append(path[:])
        for i in range(start, len(nums)):
            path.append(nums[i])
            explore(i + 1)
            path.pop()

    explore(0)
    return res

class Solution {
    public List<List<Integer>> subsets(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        explore(nums, 0, new ArrayList<>(), res);
        return res;
    }

    private void explore(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {
        res.add(new ArrayList<>(path));
        for (int i = start; i < nums.length; i++) {
            path.add(nums[i]);
            explore(nums, i + 1, path, res);
            path.remove(path.size() - 1);
        }
    }
}

def permutations(nums):
    res = []

    def place(first):
        if first == len(nums):
            res.append(nums[:])
            return
        for i in range(first, len(nums)):
            nums[first], nums[i] = nums[i], nums[first]
            place(first + 1)
            nums[first], nums[i] = nums[i], nums[first]

    place(0)
    return res

class Solution {
    public List<List<Integer>> permutations(int[] nums) {
        List<List<Integer>> res = new ArrayList<>();
        place(nums, 0, res);
        return res;
    }

    private void place(int[] nums, int first, List<List<Integer>> res) {
        if (first == nums.length) {
            List<Integer> p = new ArrayList<>();
            for (int x : nums) p.add(x);
            res.add(p);
            return;
        }
        for (int i = first; i < nums.length; i++) {
            int t = nums[first]; nums[first] = nums[i]; nums[i] = t;
            place(nums, first + 1, res);
            t = nums[first]; nums[first] = nums[i]; nums[i] = t;
        }
    }
}

def combinations(candidates, target):
    res, path = [], []

    def explore(start, remaining):
        if remaining == 0:
            res.append(path[:])
            return
        for i in range(start, len(candidates)):
            if candidates[i] <= remaining:
                path.append(candidates[i])
                explore(i, remaining - candidates[i])
                path.pop()

    explore(0, target)
    return res

class Solution {
    public List<List<Integer>> combinations(int[] candidates, int target) {
        List<List<Integer>> res = new ArrayList<>();
        explore(candidates, 0, target, new ArrayList<>(), res);
        return res;
    }

    private void explore(int[] c, int start, int remaining, List<Integer> path, List<List<Integer>> res) {
        if (remaining == 0) { res.add(new ArrayList<>(path)); return; }
        for (int i = start; i < c.length; i++) {
            if (c[i] > remaining) continue;
            path.add(c[i]);
            explore(c, i, remaining - c[i], path, res);
            path.remove(path.size() - 1);
        }
    }
}

def balanced(n):
    res = []

    def build(path, opened, closed):
        if len(path) == 2 * n:
            res.append(path)
            return
        if opened < n:
            build(path + "(", opened + 1, closed)
        if closed < opened:
            build(path + ")", opened, closed + 1)

    build("", 0, 0)
    return res

class Solution {
    public List<String> balanced(int n) {
        List<String> res = new ArrayList<>();
        build("", 0, 0, n, res);
        return res;
    }

    private void build(String path, int opened, int closed, int n, List<String> res) {
        if (path.length() == 2 * n) { res.add(path); return; }
        if (opened < n) build(path + "(", opened + 1, closed, n, res);
        if (closed < opened) build(path + ")", opened, closed + 1, n, res);
    }
}

def letter_combos(digits):
    keys = {"2": "abc", "3": "def", "4": "ghi", "5": "jkl", "6": "mno", "7": "pqrs", "8": "tuv", "9": "wxyz"}
    res = []

    def build(i, path):
        if i == len(digits):
            res.append(path)
            return
        for ch in keys[digits[i]]:
            build(i + 1, path + ch)

    if digits:
        build(0, "")
    return res

class Solution {
    private static final String[] KEYS = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};

    public List<String> letterCombos(String digits) {
        List<String> res = new ArrayList<>();
        if (!digits.isEmpty()) build(digits, 0, "", res);
        return res;
    }

    private void build(String digits, int i, String path, List<String> res) {
        if (i == digits.length()) { res.add(path); return; }
        for (char ch : KEYS[digits.charAt(i) - '0'].toCharArray()) build(digits, i + 1, path + ch, res);
    }
}

def word_search(board, word):
    m, n = len(board), len(board[0])

    def dfs(r, c, k):
        if k == len(word):
            return True
        if not (0 <= r < m and 0 <= c < n) or board[r][c] != word[k]:
            return False
        board[r][c] = "#"
        found = dfs(r + 1, c, k + 1) or dfs(r - 1, c, k + 1) or dfs(r, c + 1, k + 1) or dfs(r, c - 1, k + 1)
        board[r][c] = word[k]
        return found

    return any(dfs(r, c, 0) for r in range(m) for c in range(n))

class Solution {
    public boolean wordSearch(char[][] board, String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(board, word, r, c, 0)) return true;
        return false;
    }

    private boolean dfs(char[][] b, String w, int r, int c, int k) {
        if (k == w.length()) return true;
        if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || b[r][c] != w.charAt(k)) return false;
        b[r][c] = '#';
        boolean found = dfs(b, w, r + 1, c, k + 1) || dfs(b, w, r - 1, c, k + 1) || dfs(b, w, r, c + 1, k + 1) || dfs(b, w, r, c - 1, k + 1);
        b[r][c] = w.charAt(k);
        return found;
    }
}

def count_queens(n):
    cols, diag, anti = set(), set(), set()
    count = 0

    def place(row):
        nonlocal count
        if row == n:
            count += 1
            return
        for c in range(n):
            if c in cols or row - c in diag or row + c in anti:
                continue
            cols.add(c), diag.add(row - c), anti.add(row + c)
            place(row + 1)
            cols.remove(c), diag.remove(row - c), anti.remove(row + c)

    place(0)
    return count

class Solution {
    private int count;

    public int countQueens(int n) {
        count = 0;
        place(0, n, new boolean[n], new boolean[2 * n], new boolean[2 * n]);
        return count;
    }

    private void place(int row, int n, boolean[] cols, boolean[] diag, boolean[] anti) {
        if (row == n) { count++; return; }
        for (int c = 0; c < n; c++) {
            if (cols[c] || diag[row - c + n] || anti[row + c]) continue;
            cols[c] = diag[row - c + n] = anti[row + c] = true;
            place(row + 1, n, cols, diag, anti);
            cols[c] = diag[row - c + n] = anti[row + c] = false;
        }
    }
}

def climb(n):
    prev, cur = 1, 1
    for step in range(2, n + 1):
        prev, cur = cur, prev + cur
    return cur

class Solution {
    public int climb(int n) {
        int prev = 1, cur = 1;
        for (int step = 2; step <= n; step++) { int next = prev + cur; prev = cur; cur = next; }
        return cur;
    }
}

def cheapest_climb(cost):
    a, b = cost[0], cost[1]
    for i in range(2, len(cost)):
        a, b = b, cost[i] + min(a, b)
    return min(a, b)

class Solution {
    public int cheapestClimb(int[] cost) {
        int a = cost[0], b = cost[1];
        for (int i = 2; i < cost.length; i++) { int c = cost[i] + Math.min(a, b); a = b; b = c; }
        return Math.min(a, b);
    }
}

def rob(nums):
    skip = take = 0
    for i, x in enumerate(nums):
        skip, take = take, max(take, skip + x)
    return take

class Solution {
    public int rob(int[] nums) {
        int skip = 0, take = 0;
        for (int x : nums) { int next = Math.max(take, skip + x); skip = take; take = next; }
        return take;
    }
}

def rob_circle(nums):
    def line(houses):
        skip = take = 0
        for x in houses:
            skip, take = take, max(take, skip + x)
        return take

    if len(nums) == 1:
        return nums[0]
    return max(line(nums[1:]), line(nums[:-1]))

class Solution {
    public int robCircle(int[] nums) {
        if (nums.length == 1) return nums[0];
        return Math.max(line(nums, 1, nums.length), line(nums, 0, nums.length - 1));
    }

    private int line(int[] nums, int from, int to) {
        int skip = 0, take = 0;
        for (int i = from; i < to; i++) { int next = Math.max(take, skip + nums[i]); skip = take; take = next; }
        return take;
    }
}

def fewest_coins(coins, amount):
    best = [0] + [amount + 1] * amount
    for a in range(1, amount + 1):
        best[a] = min([best[a - c] + 1 for c in coins if c <= a] + [amount + 1])
    return best[amount] if best[amount] <= amount else -1

class Solution {
    public int fewestCoins(int[] coins, int amount) {
        int[] best = new int[amount + 1];
        Arrays.fill(best, amount + 1);
        best[0] = 0;
        for (int a = 1; a <= amount; a++)
            for (int c : coins) if (c <= a) best[a] = Math.min(best[a], best[a - c] + 1);
        return best[amount] <= amount ? best[amount] : -1;
    }
}

def change_ways(amount, coins):
    ways = [1] + [0] * amount
    for coin in coins:
        for a in range(coin, amount + 1):
            ways[a] += ways[a - coin]
    return ways[amount]

class Solution {
    public int changeWays(int amount, int[] coins) {
        int[] ways = new int[amount + 1];
        ways[0] = 1;
        for (int coin : coins)
            for (int a = coin; a <= amount; a++) ways[a] += ways[a - coin];
        return ways[amount];
    }
}

import bisect

def longest_rising(nums):
    tails = []
    for i, x in enumerate(nums):
        k = bisect.bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x
    return len(tails)

class Solution {
    public int longestRising(int[] nums) {
        int[] tails = new int[nums.length];
        int size = 0;
        for (int x : nums) {
            int lo = 0, hi = size;
            while (lo < hi) { int mid = (lo + hi) >>> 1; if (tails[mid] < x) lo = mid + 1; else hi = mid; }
            tails[lo] = x;
            if (lo == size) size++;
        }
        return size;
    }
}

def lcs(a, b):
    prev = [0] * (len(b) + 1)
    for i in range(1, len(a) + 1):
        cur = [0] * (len(b) + 1)
        for j in range(1, len(b) + 1):
            cur[j] = prev[j - 1] + 1 if a[i - 1] == b[j - 1] else max(prev[j], cur[j - 1])
        prev = cur
    return prev[-1]

class Solution {
    public int lcs(String a, String b) {
        int[] prev = new int[b.length() + 1];
        for (int i = 1; i <= a.length(); i++) {
            int[] cur = new int[b.length() + 1];
            for (int j = 1; j <= b.length(); j++)
                cur[j] = a.charAt(i - 1) == b.charAt(j - 1) ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
            prev = cur;
        }
        return prev[b.length()];
    }
}

def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i in range(1, len(a) + 1):
        cur = [i] + [0] * len(b)
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j - 1], prev[j], cur[j - 1])
        prev = cur
    return prev[-1]

class Solution {
    public int editDistance(String a, String b) {
        int[] prev = new int[b.length() + 1];
        for (int j = 0; j <= b.length(); j++) prev[j] = j;
        for (int i = 1; i <= a.length(); i++) {
            int[] cur = new int[b.length() + 1];
            cur[0] = i;
            for (int j = 1; j <= b.length(); j++)
                cur[j] = a.charAt(i - 1) == b.charAt(j - 1) ? prev[j - 1] : 1 + Math.min(prev[j - 1], Math.min(prev[j], cur[j - 1]));
            prev = cur;
        }
        return prev[b.length()];
    }
}

def word_split(s, words):
    vocab = set(words)
    ok = [True] + [False] * len(s)
    for i in range(1, len(s) + 1):
        ok[i] = any(ok[j] and s[j:i] in vocab for j in range(i))
    return ok[-1]

class Solution {
    public boolean wordSplit(String s, String[] words) {
        Set<String> vocab = new HashSet<>(Arrays.asList(words));
        boolean[] ok = new boolean[s.length() + 1];
        ok[0] = true;
        for (int i = 1; i <= s.length(); i++)
            for (int j = 0; j < i && !ok[i]; j++) ok[i] = ok[j] && vocab.contains(s.substring(j, i));
        return ok[s.length()];
    }
}

def decode_ways(s):
    two_back, one_back = 1, 1 if s[0] != "0" else 0
    for i in range(2, len(s) + 1):
        cur = one_back if s[i - 1] != "0" else 0
        if "10" <= s[i - 2:i] <= "26":
            cur += two_back
        two_back, one_back = one_back, cur
    return one_back

class Solution {
    public int decodeWays(String s) {
        int twoBack = 1, oneBack = s.charAt(0) != '0' ? 1 : 0;
        for (int i = 2; i <= s.length(); i++) {
            int cur = s.charAt(i - 1) != '0' ? oneBack : 0;
            int two = Integer.parseInt(s.substring(i - 2, i));
            if (two >= 10 && two <= 26) cur += twoBack;
            twoBack = oneBack;
            oneBack = cur;
        }
        return oneBack;
    }
}

def can_split(nums):
    total = sum(nums)
    if total % 2:
        return False
    target, reach = total // 2, {0}
    for x in nums:
        reach |= {r + x for r in reach if r + x <= target}
    return target in reach

class Solution {
    public boolean canSplit(int[] nums) {
        int total = 0;
        for (int x : nums) total += x;
        if (total % 2 == 1) return false;
        boolean[] reach = new boolean[total / 2 + 1];
        reach[0] = true;
        for (int x : nums)
            for (int s = total / 2; s >= x; s--) reach[s] |= reach[s - x];
        return reach[total / 2];
    }
}

class Solution {
    public int maxProduct(int[] nums) {
        int hi = nums[0], lo = nums[0], best = nums[0];
        for (int i = 1; i < nums.length; i++) {
            int x = nums[i], a = hi * x, b = lo * x;
            hi = Math.max(x, Math.max(a, b));
            lo = Math.min(x, Math.min(a, b));
            best = Math.max(best, hi);
        }
        return best;
    }
}

def longest_palindrome(s):
    best = s[0]
    for center in range(2 * len(s) - 1):
        left, right = center // 2, (center + 1) // 2
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left, right = left - 1, right + 1
        if right - left - 1 > len(best):
            best = s[left + 1:right]
    return best

class Solution {
    public String longestPalindrome(String s) {
        int start = 0, len = 1;
        for (int center = 0; center < 2 * s.length() - 1; center++) {
            int left = center / 2, right = (center + 1) / 2;
            for (; left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right); left--, right++) { }
            if (right - left - 1 > len) { start = left + 1; len = right - left - 1; }
        }
        return s.substring(start, start + len);
    }
}

def count_palindromes(s):
    count = 0
    for center in range(2 * len(s) - 1):
        left, right = center // 2, (center + 1) // 2
        while left >= 0 and right < len(s) and s[left] == s[right]:
            count += 1
            left, right = left - 1, right + 1
    return count

class Solution {
    public int countPalindromes(String s) {
        int count = 0;
        for (int center = 0; center < 2 * s.length() - 1; center++)
            for (int left = center / 2, right = (center + 1) / 2;
                 left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right); left--, right++) count++;
        return count;
    }
}

def grid_paths(m, n):
    row = [1] * n
    for r in range(1, m):
        for c in range(1, n):
            row[c] += row[c - 1]
    return row[-1]

class Solution {
    public int gridPaths(int m, int n) {
        int[] row = new int[n];
        Arrays.fill(row, 1);
        for (int r = 1; r < m; r++)
            for (int c = 1; c < n; c++) row[c] += row[c - 1];
        return row[n - 1];
    }
}

def can_reach_end(nums):
    reach = 0
    for i, jump in enumerate(nums):
        if i > reach:
            return False
        reach = max(reach, i + jump)
    return True

class Solution {
    public boolean canReachEnd(int[] nums) {
        int reach = 0;
        for (int i = 0; i < nums.length; i++) {
            if (i > reach) return false;
            reach = Math.max(reach, i + nums[i]);
        }
        return true;
    }
}

def fewest_hops(nums):
    jumps = end = far = 0
    for i in range(len(nums) - 1):
        far = max(far, i + nums[i])
        if i == end:
            jumps, end = jumps + 1, far
    return jumps

class Solution {
    public int fewestHops(int[] nums) {
        int jumps = 0, end = 0, far = 0;
        for (int i = 0; i < nums.length - 1; i++) {
            far = Math.max(far, i + nums[i]);
            if (i == end) { jumps++; end = far; }
        }
        return jumps;
    }
}

def start_station(gas, cost):
    total = tank = start = 0
    for i in range(len(gas)):
        total += gas[i] - cost[i]
        tank += gas[i] - cost[i]
        if tank < 0:
            start, tank = i + 1, 0
    return start if total >= 0 else -1

class Solution {
    public int startStation(int[] gas, int[] cost) {
        int total = 0, tank = 0, start = 0;
        for (int i = 0; i < gas.length; i++) {
            total += gas[i] - cost[i];
            tank += gas[i] - cost[i];
            if (tank < 0) { start = i + 1; tank = 0; }
        }
        return total >= 0 ? start : -1;
    }
}

def partition_sizes(s):
    last = {ch: i for i, ch in enumerate(s)}
    sizes, left, end = [], 0, 0
    for right, ch in enumerate(s):
        end = max(end, last[ch])
        if right == end:
            sizes.append(right - left + 1)
            left = right + 1
    return sizes

class Solution {
    public List<Integer> partitionSizes(String s) {
        int[] last = new int[26];
        for (int i = 0; i < s.length(); i++) last[s.charAt(i) - 'a'] = i;
        List<Integer> sizes = new ArrayList<>();
        for (int right = 0, left = 0, end = 0; right < s.length(); right++) {
            end = Math.max(end, last[s.charAt(right) - 'a']);
            if (right == end) { sizes.add(right - left + 1); left = right + 1; }
        }
        return sizes;
    }
}

def content_children(greed, sizes):
    greed.sort()
    sizes.sort()
    child = 0
    for cookie in range(len(sizes)):
        if child < len(greed) and sizes[cookie] >= greed[child]:
            child += 1
    return child

class Solution {
    public int contentChildren(int[] greed, int[] sizes) {
        Arrays.sort(greed);
        Arrays.sort(sizes);
        int child = 0;
        for (int cookie = 0; cookie < sizes.length; cookie++)
            if (child < greed.length && sizes[cookie] >= greed[child]) child++;
        return child;
    }
}

def lone_number(nums):
    acc = 0
    for i, x in enumerate(nums):
        acc ^= x
    return acc

class Solution {
    public int loneNumber(int[] nums) {
        int acc = 0;
        for (int x : nums) acc ^= x;
        return acc;
    }
}

def count_bits(n):
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count

class Solution {
    public int countBits(int n) {
        int count = 0;
        for (; n != 0; n &= n - 1) count++;
        return count;
    }
}

def bit_counts(n):
    res = [0] * (n + 1)
    for i in range(1, n + 1):
        res[i] = res[i >> 1] + (i & 1)
    return res

class Solution {
    public int[] bitCounts(int n) {
        int[] res = new int[n + 1];
        for (int i = 1; i <= n; i++) res[i] = res[i >> 1] + (i & 1);
        return res;
    }
}

def missing_number(nums):
    missing = len(nums)
    for i, x in enumerate(nums):
        missing += i - x
    return missing

class Solution {
    public int missingNumber(int[] nums) {
        int missing = nums.length;
        for (int i = 0; i < nums.length; i++) missing += i - nums[i];
        return missing;
    }
}

class Solution {
    public boolean isPowerOfTwo(int n) {
        return n > 0 && (n & (n - 1)) == 0;
    }
}

def add(a, b):
    mask, max_int = 0xFFFFFFFF, 0x7FFFFFFF
    while b:
        a, b = (a ^ b) & mask, ((a & b) << 1) & mask
    return a if a <= max_int else ~(a ^ mask)

class Solution {
    public int add(int a, int b) {
        while (b != 0) {
            int carry = (a & b) << 1;
            a ^= b;
            b = carry;
        }
        return a;
    }
}

def reverse_digits(x):
    sign, x, res = (-1 if x < 0 else 1), abs(x), 0
    while x:
        x, digit = divmod(x, 10)
        res = res * 10 + digit
        if res > 2**31 - 1:
            return 0
    return sign * res

class Solution {
    public int reverseDigits(int x) {
        int res = 0;
        for (; x != 0; x /= 10) {
            if (res > Integer.MAX_VALUE / 10 || res < Integer.MIN_VALUE / 10) return 0;
            res = res * 10 + x % 10;
        }
        return res;
    }
}

def is_happy(n):
    def step(x):
        return sum(int(d) ** 2 for d in str(x))

    slow, fast = n, step(n)
    while fast != 1 and slow != fast:
        slow, fast = step(slow), step(step(fast))
    return fast == 1

class Solution {
    public boolean isHappy(int n) {
        int slow = n, fast = step(n);
        while (fast != 1 && slow != fast) { slow = step(slow); fast = step(step(fast)); }
        return fast == 1;
    }

    private int step(int x) {
        int s = 0;
        for (; x > 0; x /= 10) s += (x % 10) * (x % 10);
        return s;
    }
}

def is_palindrome_number(x):
    if x < 0 or (x % 10 == 0 and x != 0):
        return False
    half = 0
    while x > half:
        x, half = x // 10, half * 10 + x % 10
    return x == half or x == half // 10

class Solution {
    public boolean isPalindromeNumber(int x) {
        if (x < 0 || (x % 10 == 0 && x != 0)) return false;
        int half = 0;
        for (; x > half; x /= 10) half = half * 10 + x % 10;
        return x == half || x == half / 10;
    }
}

def power(x, n):
    base, e, res = (x, n, 1.0) if n >= 0 else (1 / x, -n, 1.0)
    while e:
        if e & 1:
            res *= base
        base, e = base * base, e >> 1
    return res

class Solution {
    public double power(double x, int n) {
        long e = Math.abs((long) n);
        double base = n >= 0 ? x : 1 / x, res = 1.0;
        for (; e > 0; e >>= 1, base *= base) if ((e & 1) == 1) res *= base;
        return res;
    }
}

def rotate_square(m):
    n = len(m)
    for i in range(n):
        for j in range(i + 1, n):
            m[i][j], m[j][i] = m[j][i], m[i][j]
    for row in m:
        row.reverse()

class Solution {
    public void rotateSquare(int[][] m) {
        int n = m.length;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++) { int t = m[i][j]; m[i][j] = m[j][i]; m[j][i] = t; }
        for (int[] row : m)
            for (int left = 0, right = n - 1; left < right; left++, right--) { int t = row[left]; row[left] = row[right]; row[right] = t; }
    }
}

class Solution {
    public List<Integer> spiral(int[][] matrix) {
        List<Integer> res = new ArrayList<>();
        int top = 0, bottom = matrix.length - 1, left = 0, right = matrix[0].length - 1;
        while (top <= bottom && left <= right) {
            for (int c = left; c <= right; c++) res.add(matrix[top][c]);
            top++;
            for (int r = top; r <= bottom; r++) res.add(matrix[r][right]);
            right--;
            if (top <= bottom) { for (int c = right; c >= left; c--) res.add(matrix[bottom][c]); bottom--; }
            if (left <= right) { for (int r = bottom; r >= top; r--) res.add(matrix[r][left]); left++; }
        }
        return res;
    }
}

def set_zeros(m):
    rows, cols = len(m), len(m[0])
    first_row = any(v == 0 for v in m[0])
    first_col = any(m[r][0] == 0 for r in range(rows))
    for r in range(1, rows):
        for c in range(1, cols):
            if m[r][c] == 0:
                m[r][0] = m[0][c] = 0
    for r in range(1, rows):
        for c in range(1, cols):
            if m[r][0] == 0 or m[0][c] == 0:
                m[r][c] = 0
    if first_row:
        m[0] = [0] * cols
    if first_col:
        for r in range(rows):
            m[r][0] = 0

class Solution {
    public void setZeros(int[][] m) {
        int rows = m.length, cols = m[0].length;
        boolean firstRow = false, firstCol = false;
        for (int c = 0; c < cols; c++) if (m[0][c] == 0) firstRow = true;
        for (int r = 0; r < rows; r++) if (m[r][0] == 0) firstCol = true;
        for (int r = 1; r < rows; r++)
            for (int c = 1; c < cols; c++) if (m[r][c] == 0) { m[r][0] = 0; m[0][c] = 0; }
        for (int r = 1; r < rows; r++)
            for (int c = 1; c < cols; c++) if (m[r][0] == 0 || m[0][c] == 0) m[r][c] = 0;
        if (firstRow) Arrays.fill(m[0], 0);
        if (firstCol) for (int r = 0; r < rows; r++) m[r][0] = 0;
    }
}

def staircase_search(grid, target):
    r, c = 0, len(grid[0]) - 1
    while r < len(grid) and c >= 0:
        if grid[r][c] == target:
            return True
        if grid[r][c] > target:
            c -= 1
        else:
            r += 1
    return False

class Solution {
    public boolean staircaseSearch(int[][] grid, int target) {
        int r = 0, c = grid[0].length - 1;
        while (r < grid.length && c >= 0) {
            if (grid[r][c] == target) return true;
            if (grid[r][c] > target) c--;
            else r++;
        }
        return false;
    }
}

class Trie:
    def __init__(self):
        self.root = {}

    def insert(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def _walk(self, s):
        node = self.root
        for ch in s:
            if ch not in node:
                return None
            node = node[ch]
        return node

    def search(self, word):
        node = self._walk(word)
        return node is not None and "$" in node

    def startsWith(self, prefix):
        return self._walk(prefix) is not None

class Trie {
    private final Map<Character, Trie> next = new HashMap<>();
    private boolean end;

    public void insert(String word) {
        Trie node = this;
        for (char ch : word.toCharArray()) node = node.next.computeIfAbsent(ch, k -> new Trie());
        node.end = true;
    }

    private Trie walk(String s) {
        Trie node = this;
        for (int i = 0; i < s.length() && node != null; i++) node = node.next.get(s.charAt(i));
        return node;
    }

    public boolean search(String word) { Trie n = walk(word); return n != null && n.end; }

    public boolean startsWith(String prefix) { return walk(prefix) != null; }
}

class WordDictionary:
    def __init__(self):
        self.root = {}

    def addWord(self, word):
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node["$"] = True

    def search(self, pattern):
        def dfs(node, i):
            if i == len(pattern):
                return "$" in node
            if pattern[i] == ".":
                return any(dfs(child, i + 1) for key, child in node.items() if key != "$")
            return pattern[i] in node and dfs(node[pattern[i]], i + 1)

        return dfs(self.root, 0)

class WordDictionary {
    private final WordDictionary[] next = new WordDictionary[26];
    private boolean end;

    public void addWord(String word) {
        WordDictionary node = this;
        for (char ch : word.toCharArray()) {
            if (node.next[ch - 'a'] == null) node.next[ch - 'a'] = new WordDictionary();
            node = node.next[ch - 'a'];
        }
        node.end = true;
    }

    public boolean search(String pattern) { return dfs(this, pattern, 0); }

    private boolean dfs(WordDictionary node, String p, int i) {
        if (i == p.length()) return node.end;
        char ch = p.charAt(i);
        if (ch != '.') return node.next[ch - 'a'] != null && dfs(node.next[ch - 'a'], p, i + 1);
        for (WordDictionary child : node.next) if (child != null && dfs(child, p, i + 1)) return true;
        return false;
    }
}

from collections import deque

class MovingAverage:
    def __init__(self, size):
        self.size, self.window, self.total = size, deque(), 0

    def next(self, val):
        self.window.append(val)
        self.total += val
        if len(self.window) > self.size:
            self.total -= self.window.popleft()
        return self.total / len(self.window)

class MovingAverage {
    private final int size;
    private final Deque<Integer> window = new ArrayDeque<>();
    private double total;

    MovingAverage(int size) { this.size = size; }

    public double next(int val) {
        window.addLast(val);
        total += val;
        if (window.size() > size) total -= window.pollFirst();
        return total / window.size();
    }
}

from collections import deque

class HitCounter:
    def __init__(self):
        self.hits = deque()

    def hit(self, t):
        self.hits.append(t)

    def getHits(self, t):
        while self.hits and self.hits[0] <= t - 300:
            self.hits.popleft()
        return len(self.hits)

class HitCounter {
    private final Deque<Integer> hits = new ArrayDeque<>();

    public void hit(int t) { hits.addLast(t); }

    public int getHits(int t) {
        while (!hits.isEmpty() && hits.peekFirst() <= t - 300) hits.pollFirst();
        return hits.size();
    }
}

def chunk_tokens(tokens, size, overlap):
    chunks, left = [], 0
    while left < len(tokens):
        right = min(left + size, len(tokens))
        chunks.append(tokens[left:right])
        if right == len(tokens):
            break
        left += size - overlap
    return chunks

class Solution {
    public List<List<String>> chunkTokens(String[] tokens, int size, int overlap) {
        List<List<String>> chunks = new ArrayList<>();
        for (int left = 0; left < tokens.length; left += size - overlap) {
            int right = Math.min(left + size, tokens.length);
            chunks.add(Arrays.asList(tokens).subList(left, right));
            if (right == tokens.length) break;
        }
        return chunks;
    }
}

def rolling_average(latencies, k):
    res, total, left = [], 0, 0
    for right in range(len(latencies)):
        total += latencies[right]
        if right - left + 1 > k:
            total -= latencies[left]
            left += 1
        if right - left + 1 == k:
            res.append(total / k)
    return res

class Solution {
    public List<Double> rollingAverage(int[] latencies, int k) {
        List<Double> res = new ArrayList<>();
        long sum = 0;
        for (int right = 0, left = 0; right < latencies.length; right++) {
            sum += latencies[right];
            for (; right - left + 1 > k; left++) sum -= latencies[left];
            if (right - left + 1 == k) res.add((double) sum / k);
        }
        return res;
    }
}

from collections import deque

class RateLimiter:
    def __init__(self, limit, window):
        self.limit, self.window, self.log = limit, window, deque()

    def allow(self, t):
        while self.log and t - self.log[0] >= self.window:
            self.log.popleft()
        if len(self.log) < self.limit:
            self.log.append(t)
            return True
        return False

class RateLimiter {
    private final int limit, window;
    private final Deque<Integer> log = new ArrayDeque<>();

    RateLimiter(int limit, int window) { this.limit = limit; this.window = window; }

    public boolean allow(int t) {
        while (!log.isEmpty() && t - log.peekFirst() >= window) log.pollFirst();
        if (log.size() < limit) { log.addLast(t); return true; }
        return false;
    }
}

def max_documents(tokens, budget):
    total, best, left = 0, 0, 0
    for right in range(len(tokens)):
        total += tokens[right]
        while total > budget:
            total -= tokens[left]
            left += 1
        best = max(best, right - left + 1)
    return best

class Solution {
    public int maxDocuments(int[] tokens, int budget) {
        int sum = 0, best = 0, left = 0;
        for (int right = 0; right < tokens.length; right++) {
            sum += tokens[right];
            for (; sum > budget; sum -= tokens[left], left++) { }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

class Solution {
    public int[] topKSimilar(double[][] vectors, double[] query, int k) {
        double qn = norm(query);
        PriorityQueue<double[]> heap = new PriorityQueue<>((a, b) -> a[0] != b[0] ? Double.compare(a[0], b[0]) : Double.compare(b[1], a[1]));
        for (int i = 0; i < vectors.length; i++) {
            double dot = 0;
            for (int d = 0; d < query.length; d++) dot += vectors[i][d] * query[d];
            heap.add(new double[]{dot / (norm(vectors[i]) * qn), i});
            if (heap.size() > k) heap.poll();
        }
        int[] res = new int[heap.size()];
        for (int j = res.length - 1; j >= 0; j--) res[j] = (int) heap.poll()[1];
        return res;
    }

    private double norm(double[] v) {
        double s = 0;
        for (double x : v) s += x * x;
        return Math.sqrt(s);
    }
}

class Solution {
    public double[] softmax(double[] logits) {
        double m = Double.NEGATIVE_INFINITY, total = 0;
        for (double x : logits) m = Math.max(m, x);
        double[] p = new double[logits.length];
        for (int i = 0; i < p.length; i++) total += p[i] = Math.exp(logits[i] - m);
        for (int i = 0; i < p.length; i++) p[i] /= total;
        return p;
    }
}

def merge_most_frequent(tokens):
    counts, first = {}, {}
    for i in range(len(tokens) - 1):
        pair = (tokens[i], tokens[i + 1])
        counts[pair] = counts.get(pair, 0) + 1
        first.setdefault(pair, i)
    if not counts:
        return tokens
    best = max(counts, key=lambda p: (counts[p], -first[p]))
    out, i = [], 0
    while i < len(tokens):
        if i + 1 < len(tokens) and (tokens[i], tokens[i + 1]) == best:
            out.append(tokens[i] + tokens[i + 1])
            i += 2
        else:
            out.append(tokens[i])
            i += 1
    return out

class Solution {
    public List<String> mergeMostFrequent(String[] tokens) {
        if (tokens.length < 2) return Arrays.asList(tokens);
        Map<String, int[]> stats = new HashMap<>();
        String best = null;
        for (int i = 0; i + 1 < tokens.length; i++) {
            String key = tokens[i] + "\u0000" + tokens[i + 1];
            int[] s = stats.computeIfAbsent(key, x -> new int[]{0, stats.size()});
            s[0]++;
        }
        for (Map.Entry<String, int[]> e : stats.entrySet()) {
            int[] s = e.getValue(), b = best == null ? null : stats.get(best);
            if (b == null || s[0] > b[0] || (s[0] == b[0] && s[1] < b[1])) best = e.getKey();
        }
        List<String> out = new ArrayList<>();
        for (int i = 0; i < tokens.length; i++) {
            if (i + 1 < tokens.length && (tokens[i] + "\u0000" + tokens[i + 1]).equals(best)) out.add(tokens[i] + tokens[++i]);
            else out.add(tokens[i]);
        }
        return out;
    }
}

def precision_at_k(retrieved, relevant, k):
    rel, hits = set(relevant), 0
    for i, doc in enumerate(retrieved[:k]):
        if doc in rel:
            hits += 1
    return hits / k

class Solution {
    public double precisionAtK(String[] retrieved, String[] relevant, int k) {
        Set<String> rel = new HashSet<>(Arrays.asList(relevant));
        int hits = 0;
        for (int i = 0; i < Math.min(k, retrieved.length); i++) if (rel.contains(retrieved[i])) hits++;
        return (double) hits / k;
    }
}

class Solution {
    public List<Integer> mergeShards(int[][] shards, int n) {
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> b[0] - a[0]);
        for (int i = 0; i < shards.length; i++) if (shards[i].length > 0) heap.add(new int[]{shards[i][0], i, 0});
        List<Integer> res = new ArrayList<>();
        while (!heap.isEmpty() && res.size() < n) {
            int[] top = heap.poll();
            res.add(top[0]);
            int i = top[1], j = top[2] + 1;
            if (j < shards[i].length) heap.add(new int[]{shards[i][j], i, j});
        }
        return res;
    }
}

from collections import OrderedDict

class LRUCache:
    def __init__(self, capacity):
        self.capacity, self.data = capacity, OrderedDict()

    def get(self, key):
        if key not in self.data:
            return -1
        self.data.move_to_end(key)
        return self.data[key]

    def put(self, key, value):
        self.data[key] = value
        self.data.move_to_end(key)
        if len(self.data) > self.capacity:
            self.data.popitem(last=False)

class LRUCache {
    private final int capacity;
    private final LinkedHashMap<Integer, Integer> data;

    LRUCache(int capacity) {
        this.capacity = capacity;
        this.data = new LinkedHashMap<>(16, 0.75f, true) {
            protected boolean removeEldestEntry(Map.Entry<Integer, Integer> e) { return size() > LRUCache.this.capacity; }
        };
    }

    public int get(int key) { return data.getOrDefault(key, -1); }

    public void put(int key, int value) { data.put(key, value); }
}

from collections import OrderedDict, defaultdict

class LFUCache:
    def __init__(self, capacity):
        self.capacity, self.vals, self.freq, self.min_freq = capacity, {}, {}, 0
        self.groups = defaultdict(OrderedDict)

    def _touch(self, key):
        f = self.freq[key]
        del self.groups[f][key]
        if not self.groups[f]:
            del self.groups[f]
            if self.min_freq == f:
                self.min_freq += 1
        self.freq[key] = f + 1
        self.groups[f + 1][key] = None

    def get(self, key):
        if key not in self.vals:
            return -1
        self._touch(key)
        return self.vals[key]

    def put(self, key, value):
        if self.capacity == 0:
            return
        if key in self.vals:
            self.vals[key] = value
            self._touch(key)
            return
        if len(self.vals) == self.capacity:
            old, _ = self.groups[self.min_freq].popitem(last=False)
            del self.vals[old], self.freq[old]
        self.vals[key], self.freq[key], self.min_freq = value, 1, 1
        self.groups[1][key] = None

class LFUCache {
    private final int capacity;
    private int minFreq = 0;
    private final Map<Integer, Integer> vals = new HashMap<>(), freq = new HashMap<>();
    private final Map<Integer, LinkedHashSet<Integer>> groups = new HashMap<>();

    LFUCache(int capacity) { this.capacity = capacity; }

    private void touch(int key) {
        int f = freq.get(key);
        groups.get(f).remove(key);
        if (groups.get(f).isEmpty()) { groups.remove(f); if (minFreq == f) minFreq++; }
        freq.put(key, f + 1);
        groups.computeIfAbsent(f + 1, x -> new LinkedHashSet<>()).add(key);
    }

    public int get(int key) {
        if (!vals.containsKey(key)) return -1;
        touch(key);
        return vals.get(key);
    }

    public void put(int key, int value) {
        if (capacity == 0) return;
        if (vals.containsKey(key)) { vals.put(key, value); touch(key); return; }
        if (vals.size() == capacity) {
            int old = groups.get(minFreq).iterator().next();
            groups.get(minFreq).remove(old);
            vals.remove(old);
            freq.remove(old);
        }
        vals.put(key, value);
        freq.put(key, 1);
        minFreq = 1;
        groups.computeIfAbsent(1, x -> new LinkedHashSet<>()).add(key);
    }
}

class TokenBucket:
    def __init__(self, capacity, rate):
        self.capacity, self.rate, self.tokens, self.last = capacity, rate, capacity, 0

    def allow(self, t):
        self.tokens = min(self.capacity, self.tokens + (t - self.last) * self.rate)
        self.last = t
        if self.tokens > 0:
            self.tokens -= 1
            return True
        return False

class TokenBucket {
    private final long capacity, rate;
    private long tokens, last = 0;

    TokenBucket(int capacity, int rate) { this.capacity = capacity; this.rate = rate; this.tokens = capacity; }

    public boolean allow(int t) {
        tokens = Math.min(capacity, tokens + (t - last) * rate);
        last = t;
        if (tokens > 0) { tokens--; return true; }
        return false;
    }
}

import bisect

class HashRing:
    def __init__(self):
        self.points, self.owner = [], {}

    @staticmethod
    def h(s):
        return sum((i + 1) * ord(c) for i, c in enumerate(s)) % 360

    def addNode(self, name):
        p = self.h(name)
        bisect.insort(self.points, p)
        self.owner[p] = name

    def removeNode(self, name):
        p = self.h(name)
        self.points.remove(p)
        del self.owner[p]

    def getNode(self, key):
        p = self.h(key)
        i = bisect.bisect_left(self.points, p) % len(self.points)
        return self.owner[self.points[i]]

class HashRing {
    private final TreeMap<Integer, String> ring = new TreeMap<>();

    private static int h(String s) {
        int x = 0;
        for (int i = 0; i < s.length(); i++) x += (i + 1) * s.charAt(i);
        return x % 360;
    }

    public void addNode(String name) { ring.put(h(name), name); }

    public void removeNode(String name) { ring.remove(h(name)); }

    public String getNode(String key) {
        Map.Entry<Integer, String> e = ring.ceilingEntry(h(key));
        return (e != null ? e : ring.firstEntry()).getValue();
    }
}

class CircuitBreaker:
    def __init__(self, threshold, cooldown):
        self.threshold, self.cooldown = threshold, cooldown
        self.state, self.failures, self.opened_at = "closed", 0, 0

    def allow(self, t):
        if self.state == "open" and t - self.opened_at >= self.cooldown:
            self.state = "half-open"
        return self.state != "open"

    def record(self, t, ok):
        if ok:
            self.state, self.failures = "closed", 0
        else:
            self.failures += 1
            if self.state == "half-open" or self.failures >= self.threshold:
                self.state, self.opened_at = "open", t

    def getState(self):
        return self.state

class CircuitBreaker {
    private final int threshold, cooldown;
    private String state = "closed";
    private int failures = 0, openedAt = 0;

    CircuitBreaker(int threshold, int cooldown) { this.threshold = threshold; this.cooldown = cooldown; }

    public boolean allow(int t) {
        if (state.equals("open") && t - openedAt >= cooldown) state = "half-open";
        return !state.equals("open");
    }

    public void record(int t, boolean ok) {
        if (ok) { state = "closed"; failures = 0; return; }
        failures++;
        if (state.equals("half-open") || failures >= threshold) { state = "open"; openedAt = t; }
    }

    public String getState() { return state; }
}

class IdGenerator:
    def __init__(self, machine):
        self.machine, self.last, self.seq = machine, -1, 0

    def next(self, ts):
        self.seq = self.seq + 1 if ts == self.last else 0
        self.last = ts
        return (ts << 22) | (self.machine << 12) | self.seq

class IdGenerator {
    private final long machine;
    private long last = -1, seq = 0;

    IdGenerator(int machine) { this.machine = machine; }

    public long next(long ts) {
        seq = ts == last ? seq + 1 : 0;
        last = ts;
        return (ts << 22) | (machine << 12) | seq;
    }
}

import bisect

class VersionedStore:
    def __init__(self):
        self.times, self.values = {}, {}

    def set(self, key, value, t):
        self.times.setdefault(key, []).append(t)
        self.values.setdefault(key, []).append(value)

    def get(self, key, t):
        i = bisect.bisect_right(self.times.get(key, []), t) - 1
        return self.values[key][i] if i >= 0 else ""

class VersionedStore {
    private final Map<String, TreeMap<Integer, String>> data = new HashMap<>();

    public void set(String key, String value, int t) {
        data.computeIfAbsent(key, k -> new TreeMap<>()).put(t, value);
    }

    public String get(String key, int t) {
        Map.Entry<Integer, String> e = data.getOrDefault(key, new TreeMap<>()).floorEntry(t);
        return e == null ? "" : e.getValue();
    }
}

